-- Strategies for "information" in the four synthetic spaces, grounded in Eirdosh and Hanisch (2026, in press).
-- Generated by scripts/generate_information_strategy_migration.mjs; do not hand-edit.
--
-- Each space gets one thread "Information across the grade bands" with a station per use, proposed concepts where its vocabulary
-- cannot carry the strategy, stage tags to those concepts, additive notes on existing concepts, stage tags to AI4K12 elements the space
-- already holds, one introduction paragraph and literature rows. The three disciplinary spaces treat information in their own terms and
-- differ on purpose. The Interdisciplinary space joins them and states what does not carry over between domains.
-- Everything is AI-drafted, status 'proposed', unreviewed by a subject expert. Accepted definitions are not changed.
-- Rollback: DELETE FROM lpm_threads WHERE slug = 'information-across-the-bands' (stations by cascade);
--   DELETE FROM lpm_schema_elements WHERE metadata->>'information_strategy' = 'true' (new concepts and meanings, tags by cascade);
--   UPDATE lpm_schema_elements SET metadata = metadata - 'information_strategy_note' WHERE metadata ? 'information_strategy_note'.

SET search_path = public, extensions;

-- Bio-Core
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bb9d0208-b1ad-529d-a609-0f536dbe448c', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Information', 'What a living system receives, stores, copies, passes on, processes and responds to. It has three common uses: genetic information, which DNA stores, offspring inherit and which affects the proteins made; what senses take in; and what signals carry between cells or organisms.', NULL, '{"definition":"What a living system receives, stores, copies, passes on, processes and responds to. It has three common uses: genetic information, which DNA stores, offspring inherit and which affects the proteins made; what senses take in; and what signals carry between cells or organisms.","vocabulary":"BIO-CORE-proposed","conceptbase_id":"OE-CONCEPT-bio-core-information","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"The accepted Gene and Inheritance definitions use the word, the German standards name it a core concept, and NGSS use it in several senses. Bio-Core has no concept for it. Students meet it in Sachsen Kl. 5, 8 and 10.","excludes":"Meaning, understanding or intention in a cell, gene or animal. Human messages, media, data and bits. Any account of how structure relates to meaning, which the Interdisciplinary space covers.","basis":["KMK 2020 p.19 as quoted in paper p.6","NGSS Table 1 in paper p.7-8","OE-COMPETENCY-ngss-life-science-ms-ls1-8","OE-COMPETENCY-ngss-life-science-ms-ls3-2","OE-COMPETENCY-ngss-life-science-hs-ls3-1","Project lead instruction, 2026-10-27"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4635a841-835f-5c28-b920-11a865244eef', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Signal', 'A chemical, electrical, sound or light change that passes from one part of a living system to another, or from one organism to another, and is followed by a response in the receiver. Hormones, nerve impulses and animal calls are examples.', NULL, '{"definition":"A chemical, electrical, sound or light change that passes from one part of a living system to another, or from one organism to another, and is followed by a response in the receiver. Hormones, nerve impulses and animal calls are examples.","vocabulary":"BIO-CORE-proposed","conceptbase_id":"OE-CONCEPT-bio-core-signal","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"Both standards use signals for what passes between cells and between organisms (signal transduction, messages from receptors, communication). Bio-Core has no concept for what passes between parts.","excludes":"A message written by a sender who means something. Meaning or intent in cells or animals. The theory of cues, honesty and signaling games, which the Interdisciplinary space covers.","basis":["KMK 2020 p.19 as quoted in paper p.6 (signal transduction)","OE-COMPETENCY-ngss-life-science-ms-ls1-8","NGSS 1-LS1-2 (signals that offspring make; checked on nextgenscience.org; absent from CompetencyBase)","Sachsen Kl. 8 Sinnesorgane, Nerven- und Hormonsystem (lehrplan-522-1/lernbereich-7406-1)"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('28bb57fc-1f27-5f20-bca0-46c1d41d0c42', '28997544-0d87-4b05-9ee2-7c474513c108', 'concept', 'Communication', 'An exchange of signals between organisms, or between parts of one organism, in which a response follows in the receiver. It happens at several levels: between cells, between organs, and between animals, as in courtship, alarm calls and life in groups.', NULL, '{"definition":"An exchange of signals between organisms, or between parts of one organism, in which a response follows in the receiver. It happens at several levels: between cells, between organs, and between animals, as in courtship, alarm calls and life in groups.","vocabulary":"BIO-CORE-proposed","conceptbase_id":"OE-CONCEPT-bio-core-communication","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"KMK names communication at several system levels as part of the Basiskonzept, and Sachsen Kl. 5 and 6 teach it for birds, mammals and the honeybee. No Bio-Core concept covers it.","excludes":"Language, media or any exchange of meaning between people. Any sender who intends to tell, warn or deceive. Any member that directs a group.","basis":["KMK 2020 p.19 as quoted in paper p.6","Sachsen Kl. 5 Vögel and Säugetiere (lehrplan-522-1/lernbereich-7067-1 and 7068-1) and Kl. 6 Wirbellose (7202-1)","NGSS 1-LS1-2 (checked on nextgenscience.org; absent from CompetencyBase)"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The accepted definition says ''encoding information''. Here that phrase is read as the standards read it: the base sequence is copied and affects which protein is made. ''Code'' and ''instructions'' are figures of speech. Cell conditions also matter, and nobody wrote the sequence.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'edba5b0a-400d-5b77-a2b3-672ff3ad13bd';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The accepted definition speaks of genetic information passed to offspring. Stations describe this as copying: asexual reproduction gives identical copies, sexual reproduction gives new combinations (NGSS MS-LS3-2). Nothing is sent or told.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'cae5dbad-0106-51c0-8818-aaacab89470e';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"A mutation is a change in the copied information. Its effect, if any, shows in the protein made and the trait that follows (NGSS MS-LS3-1). Mutations arise without regard to need, which keeps the existing B1 point about random variation.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'eeb66b9f-2d89-5cae-bed1-eac6f60037b1';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Alleles are alternative forms of the stored information at one place on a chromosome. A receptor gene with two alleles can give two versions of the receptor protein, and so two responses to the same signal.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'd34950cc-ba40-5ea7-9d9c-37a4dd862ac3';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Sense organs and signalling behaviours can be tested as adaptations like any other trait, with the same four components and the stage''s rival explanations. Stations describe what the trait receives or sends. They give no separate theory of how signals evolve.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'd68724fa-f299-5752-a49b-789f6416270d';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Molecular trees compare sequences. Here the sequences are evidence that scientists read, which differs from the information an organism copies and uses (NGSS HS-LS4-1). The B3:9-12 station asks students to say which use is meant.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '3bb15af5-a22b-512d-a3fb-708bc38f3d87';
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, evidence_note, gaps, status)
VALUES ('b6879e22-85d3-55f8-ba6e-3847b24f89dd', '28997544-0d87-4b05-9ee2-7c474513c108', '489efe08-9c39-4601-8f31-fa40dccc8d5b', 'information-across-the-bands', 'Information across the grade bands', 'vertical_horizontal', 'In Bio-Core, information is what a living system receives, stores, copies, passes on, processes and responds to, as the standards use the word. It covers genetic information that is copied and inherited, what organisms take in through their senses, and signals between cells and between organisms. Every description says what is received and what follows.', 'Information in Bio-Core. Sense: In Bio-Core, information is what a living system receives, stores, copies, passes on, processes and responds to, as the standards use the word. It covers genetic information that is copied and inherited, what organisms take in through their senses, and signals between cells and between organisms. Every description says what is received and what follows. Boundary: Biology only, at the level of the standards. Bio-Core says what is received, copied, passed on and followed by a response, and stops there. It teaches no link between structure and meaning. No cell, gene or animal understands, intends or wants anything. Human messages, media, bits and codes written by someone belong to other spaces. The deeper analysis sits in the Interdisciplinary space. Aim: Bio-Core explains evolution as variation, inheritance and selection on populations, with no organism that wants or plans. Its Gene and Inheritance definitions already use the word information without a concept behind it. The new concepts define the word as the standards use it. Three stations carry a selection question, three follow copying and descent, and two (K-2 and the ant trail) only describe what is received and passed on. Structure and meaning are left to the Interdisciplinary space. Sequence: The order follows the standards. The paper''s structure-first step stays with the Interdisciplinary space. K-2: something is taken in and a response follows. 3-5: two animals, with what passes between them. 6-8: three steps, copying of genetic information, a receptor that starts a signal, and a trail made by many local signals. 9-12: molecular steps, two uses of the word, and a group of cells. Paper''s three dimensions: structure without a sender is translated (Only the descriptive part the standards share: a gene''s sequence is stored in DNA and copied to offspring, and senses take in physical changes. The analysis of structure without a sender, and of how structure relates to meaning, is left to the Interdisciplinary space by design.); systems that use information is translated (Treated as in the standards: organisms receive, pass on and react, and cells and animals exchange signals. Bio-Core names the sender, what passes and what follows, with plain sentence frames. It builds no theory of cues, honest or dishonest signals or signaling games, and it adds no goals or intention to any animal or cell.); decentralized processing is translated (Kept light and descriptive. A trail of ants and a group of cells show a pattern that comes from many members each receiving and passing on a local signal. No member holds the whole pattern or steers it. The caution against queens, leaders and master genes is the only added idea.) False friends: Information as media or data. Sachsen Informatik Kl. 7 (''Informationen und Daten'') and Sachunterricht Kl. 4 (Medien) use the word for facts and files. Bio-Core uses it for what a living system receives, copies or passes on, and counts nothing in bits. Code. Sachsen Genetik (Kl. 10) teaches the ''genetischer Code'', and in computing a code is written by a person. In Bio-Core the genetic code is the rule that pairs each three-base group with an amino acid. It arose in evolution and nobody wrote it. Sender and receiver. Sachsen Kl. 5 Säugetiere teaches a ''Sender-Empfänger-Modell'' for dog and cat, which can suggest a sender who means to send. In Bio-Core a sender is an animal or cell whose body produces a signal. Intent plays no part. Signal. In technology it travels on a wire or through the air. Sachsen Kl. 8 speaks of Reiz, elektrische Impulse and Überträgerstoffe. Bio-Core''s Signal is any change passing between parts or organisms that is followed by a response. It says nothing on how it arose. Meaning and understanding. Ethik Kl. 7 (''Verstehen und Verständigung'') uses communication for people who understand each other. Bio-Core never says a cell, gene or animal understands. ''Carries instructions'' is a figure of speech for how a base sequence affects the protein made. Information as evidence. NGSS uses ''genetic information'' for what an organism copies and for sequences scientists compare to show common ancestry (paper Table 1, p.8). Bio-Core names which use is meant each time.', 'AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it. Grounding paper: Eirdosh and Hanisch (2026, in press).  Open checks for reviewers are under reviewNotes in scripts/data/information-strategies.json.', '["No study of students'' conceptions of information in biology exists (paper p.6) and no classroom has tested any station. Every station is a proposal.","Evidence for K-2 and 3-5 is thin. S11 shows young children give purposes to things and S15 shows second and third graders learn selection from a teacher-led unit. Nothing found tests how children describe signals.","Bio-Core has no stage for physiology. Station 4 borrows B2:6-8 through its evolution question. Nerve cell, synapse and hormone loop detail from Sachsen Kl. 8 has no home here.","Sachsen teaches genes only in Kl. 10, so station 3 comes years before students meet the word Genetik.","The standards'' own wording (''instructions'', ''code'', ''messages'') is figurative. The paper (Table 1, p.7-8) lists the risks. The caution in the concepts is short on purpose and its effect on students is untested."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d9442bd9-f704-539e-9b11-4b6d697c10cf', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', 'aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 1, 'K-2, Organisms and Their Habitats (precursor, dimension 1: structure without a sender). Children match picture cards: a body part (nose, eye, ear, shoot tip), what it takes in (smell of food, a moving shape, a sound, window light) and what follows (a hedgehog sniffs on, a bird turns its head, a seedling bends). They say ''the nose takes in the smell, then the hedgehog goes to the snail''. The teacher replaces ''it wants'' with ''then''. Example: A hedgehog''s nose picking up the smell of a snail, a bird''s eye picking up a moving shape, a seedling leaning towards window light. Shown as: Three-column picture cards: body part, what it takes in, what follows, joined by arrows. New demand: Say what passes from the surroundings to the body and what follows, with no wish word. Young children give purposes to everything, so the teacher models ''takes in, then''. No study tests this at K-2. Concepts: Information, Adaptation. Thinking tools: Tinbergen''s Questions K-2 (Thick or thin fur in a group of animals); Payoff Matrices K-2 (Green and brown caterpillars on a green leaf with). Sachsen topics: biologie Kl. 5: Merkmale des Lebens. KMK: Information und Kommunikation, Struktur und Funktion.', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', 'aac5e307-a98f-50c6-ba5d-5cc6bcd7ebdf', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('d5356cbf-268b-571f-989c-42080b8ad513', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', 'ae85f5be-aead-5819-99df-8b3d431f79d1', 2, '3-5, Trait Advantage and Simple Selection Scenarios (precursor, dimension 2: systems that use information). Students read two short stories: a hen''s alarm call and chicks that crouch, and a dog''s growl and a cat that backs away. In a four-box row they fill in who makes the sound, what passes, who takes it in and what follows. They then predict which chicks are more likely to live, those that crouch or those that do not. Example: A hen''s alarm call as a hawk passes and chicks that crouch; a dog''s growl and a cat that backs away. Shown as: Four-box row of cards: maker, what passes, receiver, what follows. New demand: Describe an exchange between two animals with no wish words, then link the response to who is more likely to live. The Kl. 5 sender-receiver sketch invites ''the dog tells the cat''. No study tests this at 3-5. Concepts: Communication, Signal, Natural Selection. Thinking tools: Tinbergen''s Questions 3-5 (Green and brown beetles on dark soil with hungry). Sachsen topics: biologie Kl. 5: Säugetiere in ihren Lebensräumen; biologie Kl. 5: Vögel in ihren Lebensräumen. KMK: Information und Kommunikation, Evolutive Entwicklung.', '28bb57fc-1f27-5f20-bca0-46c1d41d0c42', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', 'ae85f5be-aead-5819-99df-8b3d431f79d1', '28bb57fc-1f27-5f20-bca0-46c1d41d0c42', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', 'ae85f5be-aead-5819-99df-8b3d431f79d1', '4635a841-835f-5c28-b920-11a865244eef', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('aa06ed43-2073-5048-903b-d025fc147ec1', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', '8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 3, '6-8, Genes, Alleles, and the Origin of Variation (precursor, dimension 1: structure without a sender). Students lay out two bead strings for the haemoglobin gene, one with a single bead changed. They copy a string for offspring, once with a copying slip, and follow each version to the protein it leads to and the red blood cell shape. They sort sentences into ''copied'', ''changed in the copy'' and ''passed on'', and replace any wish wording. Example: One changed base in the haemoglobin gene gives a changed protein and sickle-shaped red blood cells in some people. Shown as: Bead strings, copy-step cards and a three-link chain: copy, protein, trait. New demand: Follow one copied change through to a protein and a trait. Mutations arise without regard to need, a point many students miss. The bead strings model the case and leave out how cells copy DNA. Concepts: Information, Gene, Mutation, Allele. Thinking tools: Tinbergen''s Questions 6-8 (Antibiotic resistance in a bacterial population. The variant usually). KMK: Information und Kommunikation, Evolutive Entwicklung.', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', '8a1c0b8f-8e98-526f-bd7a-8cb2795daa85', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('1eb9e4ce-c533-50b7-8a37-77312fed8f75', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', '4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 4, '6-8, The Four-Component Natural Selection Mechanism (full, dimension 2: systems that use information). Students trace a hand touching a hot surface: heat reaches a skin receptor, an impulse passes along nerves to the spinal cord and on to a muscle, and the hand pulls back. They fill the four-row sheet from the fox station. For the survival row they compare people with the reflex and rare cases of people born unable to feel pain. Example: Hand withdrawal: heat at the skin, a nerve impulse through the spinal cord, a muscle that pulls the hand back. In a rare inherited condition people feel no pain and often injure themselves badly. Shown as: Four-row sheet with a labelled body drawing showing receptor, nerve and muscle. New demand: Join a how-it-works chain (receptor, impulse, response) with an evolution question that has a variant to compare. Students often answer one question with the other (shown in university physiology), so the sheet keeps them apart. Concepts: Information, Signal, Adaptation, Natural Selection. Thinking tools: Tinbergen''s Questions 6-8 (Tameness in silver foxes bred at Novosibirsk from 1959,). Sachsen topics: biologie Kl. 8: Sinnesorgane, Nerven- und Hormonsystem des Menschen. KMK: Information und Kommunikation, Struktur und Funktion, Evolutive Entwicklung.', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', '4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', '4f1b4d5d-6232-5ef5-b44c-a850224b58a5', '4635a841-835f-5c28-b920-11a865244eef', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('61c3c50c-91fa-5995-9de8-e66ec3095995', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', '4f1b4d5d-6232-5ef5-b44c-a850224b58a5', 5, '6-8, The Four-Component Natural Selection Mechanism (precursor, dimension 3: decentralized processing). Students play ants on a floor grid. Ants that find food drop a scent card on the way back, and every ant follows the strongest scent card nearby. Food sits at one end and a nest at the other. They map what each ant takes in and passes on, watch a trail form, then ask which single ant held the route. They check that no card acts like a leader. Example: A foraging ant trail: ants that find food lay scent on the way back and others follow the stronger scent. The queen gives no orders. Shown as: Floor grid with scent cards, then a signed-arrow map with one loop. New demand: Explain a group pattern that no member holds or plans. The Kl. 6 word Tierstaat, taught with the honeybee, and a ruling-queen picture push students to look for a leader. Evidence comes from older students: a design bet. Concepts: Communication, Signal. Thinking tools: Causal Mapping 6-8 (Light and dark peppered moths on soot-darkened tree bark.); Causal Mapping 6-8 (Apple maggot flies that prefer hawthorn fruit or apple). Sachsen topics: biologie Kl. 6: Wirbellose Tiere in ihren Lebensräumen. KMK: Information und Kommunikation.', '28bb57fc-1f27-5f20-bca0-46c1d41d0c42', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', '4f1b4d5d-6232-5ef5-b44c-a850224b58a5', '28bb57fc-1f27-5f20-bca0-46c1d41d0c42', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('11214830-be03-5d23-adbd-1bee711d1947', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', '6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 6, '9-12, Population-Level Genetics and Allele Frequency (full, dimension 2: systems that use information). Students follow an allele of a colour-vision gene on the X chromosome: DNA transcribed to RNA, RNA used to build a light-receptor protein, the receptor responding to light, and a nerve signal to the brain. They compare two alleles, use the bead jar to estimate how many people carry each version, and rewrite ''code'', ''reads'' and ''instructions'' as the physical step. Example: Red-green colour vision: alleles of a light-receptor gene on the X chromosome change which colours the receptor responds to. Shown as: Chain diagram from DNA to protein to signal to brain, plus a two-column table of phrases and physical steps. New demand: Rewrite ''code'', ''reads'' and ''instructions'' as physical steps, then link the chain, allele to receptor to signal, to how often each version occurs. This needs the teacher''s lead, because the standards use those figures themselves. Concepts: Information, Signal, Allele, Gene. Thinking tools: Analogy Mapping 9-12 (A bead jar standing for the two alleles of). Sachsen topics: biologie Kl. 10: Genetik; biologie Kl. 8: Sinnesorgane, Nerven- und Hormonsystem des Menschen. KMK: Information und Kommunikation, Struktur und Funktion, Evolutive Entwicklung.', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', '6c0b740a-cb12-5c3d-8a32-75fc01624ddf', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', '6c0b740a-cb12-5c3d-8a32-75fc01624ddf', '4635a841-835f-5c28-b920-11a865244eef', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4f3f09fe-03a9-5d6c-a55c-0a0bf53d0893', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', '60df174a-b374-5cd1-9d06-9d76ecc4af9f', 7, '9-12, Evidence, Deep Time, and Patterns of Extinction (precursor, dimension 1: structure without a sender). Students compare a short stretch of the same gene from four species, count the differences and build a tree. They sort statements about ''genetic information'' into two piles: what an organism copies and uses, and what scientists read from sequences as evidence. They list the independent lines of evidence a shared ancestor would need. Example: A short stretch of beta-globin sequence from human, chimpanzee, mouse and chicken, used to build a tree. Shown as: Aligned sequence table, a tree drawing and a two-pile statement sort. New demand: Keep two uses of one phrase apart: what a cell copies and what a scientist compares. NGSS blends them. The tree work is familiar, so the new demand is naming the use each time. Concepts: Information, Phylogeny, Common Ancestor, Mutation. Thinking tools: Tinbergen''s Questions 9-12 (Flipper bones of whales compared with the arm bones). Sachsen topics: biologie Kl. 10: Genetik; biologie Kl. 10: Entstehung der Artenvielfalt. KMK: Information und Kommunikation, Evolutive Entwicklung.', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', '60df174a-b374-5cd1-9d06-9d76ecc4af9f', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('a1de01f1-7b36-5ef3-88ba-f8ca470d39e3', 'b6879e22-85d3-55f8-ba6e-3847b24f89dd', 'b8bf5ec4-fe31-593a-8177-15b8109517b4', 8, '9-12, Evaluating Adaptationist Claims (extended, dimension 3: decentralized processing). Students model bacteria as cards on a table. Each card adds signal tokens to a shared pool and switches on a light when the pool passes a level. They vary the number of cards and watch lights come on together. They write what each cell takes in and passes on, check that no cell counts the group, and test one benefit claim against a rival. Example: Glowing Vibrio bacteria in a squid''s light organ, where light switches on only when many cells are close together. Shown as: Cards and tokens on a table, then a signed-arrow map with one reinforcing loop. New demand: Explain a threshold: cells stay dark below a certain number and light up together above it, though no cell counts the group. Then test a benefit claim against a rival, as the stage asks. Concepts: Signal, Communication, Information, Adaptation. Thinking tools: Causal Mapping 6-8 (Apple maggot flies that prefer hawthorn fruit or apple); Tinbergen''s Questions 9-12 (The red colour of vertebrate blood, which comes from). Sachsen topics: biologie Kl. 9: Zusammenhänge im Ökosystem. KMK: Information und Kommunikation.', '4635a841-835f-5c28-b920-11a865244eef', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', 'b8bf5ec4-fe31-593a-8177-15b8109517b4', '4635a841-835f-5c28-b920-11a865244eef', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', 'b8bf5ec4-fe31-593a-8177-15b8109517b4', '28bb57fc-1f27-5f20-bca0-46c1d41d0c42', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('28997544-0d87-4b05-9ee2-7c474513c108', 'b8bf5ec4-fe31-593a-8177-15b8109517b4', 'bb9d0208-b1ad-529d-a609-0f536dbe448c', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
UPDATE projects SET introduction = introduction || '

Information. This space treats information in its own terms. In Bio-Core, information is what a living system receives, stores, copies, passes on, processes and responds to, as the standards use the word. It covers genetic information that is copied and inherited, what organisms take in through their senses, and signals between cells and between organisms. Every description says what is received and what follows. Bio-Core explains evolution as variation, inheritance and selection on populations, with no organism that wants or plans. Its Gene and Inheritance definitions already use the word information without a concept behind it. The new concepts define the word as the standards use it. Three stations carry a selection question, three follow copying and descent, and two (K-2 and the ant trail) only describe what is received and passed on. Structure and meaning are left to the Interdisciplinary space. The order follows the standards. The paper''s structure-first step stays with the Interdisciplinary space. K-2: something is taken in and a response follows. 3-5: two animals, with what passes between them. 6-8: three steps, copying of genetic information, a receptor that starts a signal, and a trail made by many local signals. 9-12: molecular steps, two uses of the word, and a group of cells. The strategy rests on the paper by Eirdosh and Hanisch (2026, in press) and is a proposal. AI drafted it and no subject expert has reviewed it.' WHERE id = '28997544-0d87-4b05-9ee2-7c474513c108' AND introduction NOT LIKE '%Information. This space treats information in its own terms.%';
INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes, tags)
SELECT '28997544-0d87-4b05-9ee2-7c474513c108', 'OE-LITERATURE-eirdosh-hanisch-2026', 'Understanding Information as an Interdisciplinary Concept in Biology Education', '["Eirdosh, Dustin","Hanisch, Susan"]'::jsonb, 2026, NULL, NULL, NULL, 'draft', 'Grounding paper of the information strategy of Bio-Core (AI-drafted 2026-10-27, no expert review).', ARRAY['information', 'proposed-link']::text[]
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '28997544-0d87-4b05-9ee2-7c474513c108' AND literaturebase_id = 'OE-LITERATURE-eirdosh-hanisch-2026');

-- Social-Core
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('0c562b16-dc7a-5b57-9a7c-843e0b069e2c', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'concept', 'Information', 'What people record, tell, share, withhold or check in order to act or to find out, such as a deed, a timetable, a news report or a rumour. A trace becomes information when someone reads it with a question.', NULL, '{"definition":"What people record, tell, share, withhold or check in order to act or to find out, such as a deed, a timetable, a news report or a rumour. A trace becomes information when someone reads it with a question.","vocabulary":"SOCIAL-CORE-proposed","conceptbase_id":"OE-CONCEPT-social-core-information","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"Social-Core has Communication and Knowledge but no word for the thing that is recorded, passed on and checked. Students already use the word, and Sachsen''s media and history topics use it.","excludes":"Bits, channels and noise. Cues and signals shaped by selection. DNA as a code. Data handled by machines. Knowledge itself, which a group holds and justifies.","basis":["paper p. 4-6 and 10-11","OE-LITERATURE-grossnickle-2015","OE-LITERATURE-alexander-2012","own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fee774c4-aec9-50a5-92e9-66fbc776714f', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'concept', 'Source', 'Anything people use to find something out. A trace was made for another purpose, such as a tool or a bill. A report was made to tell later people, such as a chronicle. Coins and inscriptions are both. Users weigh who made it and why.', 'a6b63554-589c-5a94-b249-250d6adb41e9', '{"definition":"Anything people use to find something out. A trace was made for another purpose, such as a tool or a bill. A report was made to tell later people, such as a chronicle. Coins and inscriptions are both. Users weigh who made it and why.","vocabulary":"SOCIAL-CORE-proposed","conceptbase_id":"OE-CONCEPT-social-core-source","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"The paper''s first dimension, structure without a sender, becomes source work in this space. German historical method separates remains from reports, and Sachsen Geschichte Kl. 5 asks students to judge what historical sources can and cannot show.","excludes":"Biological cues and signals. In computing, the place data comes from, and source code.","basis":["paper p. 10-11","Droysen, Outline of the Principles of History (Andrews 1893 translation), sections 21-24: Remains, Monuments, Sources (read)","Hildesheim history department handout ''Quellenkunde'' (2017): Überreste and Tradition, Bernheim''s pair. Handout only; primary text not read; author name unconfirmed (file says Peter Müller)","Sachsen geschichte lernbereich-766-1 and lernbereich-772-1","Sachsen technik-computer lernbereich-30700-1 (reliability of online information)","own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('14789508-8343-5763-9898-c66f4d5eab41', '7f604bf5-2f90-5f00-9160-30e9265971c4', 'concept', 'Misinformation', 'False or misleading information passed on by mistake or on purpose. On purpose it is often called disinformation. It travels by talk, press, posters and posts. Groups answer with checks, corrections, rules and people whose job is to check.', '80e5794a-74bf-5c07-a435-71b6f6c7c0c7', '{"definition":"False or misleading information passed on by mistake or on purpose. On purpose it is often called disinformation. It travels by talk, press, posters and posts. Groups answer with checks, corrections, rules and people whose job is to check.","vocabulary":"SOCIAL-CORE-proposed","conceptbase_id":"OE-CONCEPT-social-core-misinformation","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"The paper treats dishonest signals as part of receiver evolution. Social-Core needs the human case: reasons to mislead, reasons to repeat carelessly, and ways groups correct it.","excludes":"Mimicry, camouflage and false alarms in animals. Faulty output from a machine.","basis":["paper p. 20-22 (the biological case, left out here)","Sachsen ethik lernbereich-12038-1","Sachsen geschichte lernbereich-1039-1","own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The accepted definition already holds meaning and shared codes. The strategy adds one point: a message has a maker with a purpose. A trace was made for another purpose. Traces belong under Source. Misinformation sits here as a kind of message.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '80e5794a-74bf-5c07-a435-71b6f6c7c0c7';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Knowledge stays what a group holds and justifies. Records, archives and checking practices are cases of how a group justifies what it holds. Information feeds knowledge. Students often tie the two closely (paper p. 5), so stations keep them apart.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'a6b63554-589c-5a94-b249-250d6adb41e9';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Writing systems, the press, archives, courts and schools are institutions for sending, recording and checking information. Stations use them as cases of Institutions and need no new institution concept.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '4e1ba9af-f7f2-5a32-b3c5-83baca7d1265';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Norms about telling the truth, passing on gossip and keeping secrets are the informal side of information. A worn path shows a habit and may be no norm at all, since a norm needs approval and disapproval behind it.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '380fb2a2-69bf-5950-9997-0b88e441278c';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Diffusion already covers spread through contact and adoption. A rumour, a habit seen by other classes and a stadium wave show spread with nobody in charge. Each person who passes it on has reasons. No selection language is used.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '1c6776e1-7f70-52c2-8c93-00089fb0056c';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Control over what is recorded, shown or kept secret is a form of power. The rumour, grading and legend stations use it. The accepted definition is unchanged.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '834c8631-d832-5ddc-81f8-828686900d33';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"A false report pays or costs depending on who checks. The reporting station uses Incentive to show why a check changes what people say. The accepted definition is unchanged.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'd9a7d40a-15a6-5d10-a17c-777b612924a0';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Trust that others tell the truth is one form of the trust that sustains Cooperation. The passing-game station uses it. The accepted definition is unchanged.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'd7094e85-8ed0-5b69-b6e3-5fcf954eb582';
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, evidence_note, gaps, status)
VALUES ('632b26a3-cfd6-561a-95c0-e290c76bf3fb', '7f604bf5-2f90-5f00-9160-30e9265971c4', '1b76e826-b455-4897-8df8-9ace0dff1a64', 'information-across-the-bands', 'Information across the grade bands', 'vertical_horizontal', 'Information is what people record, tell, share, withhold, check and rely on to act or to find out. It includes things made for another purpose, such as a ruin or an old bill, and messages made to tell. People give it meaning together and build rules and institutions to send, keep and check it.', 'Information in Social-Core. Sense: Information is what people record, tell, share, withhold, check and rely on to act or to find out. It includes things made for another purpose, such as a ruin or an old bill, and messages made to tell. People give it meaning together and build rules and institutions to send, keep and check it. Boundary: Information is always for someone: a person or group with goals. No selection of signals, no fitness, no genes and no cultural-evolution mechanism. No bits, channels, noise or feedback loops as explanation, and no machine that understands. Signal, message, code and source keep their human sense. Spread without a central sender is explained by people''s reasons, norms and contact. Aim: The aim is to explain why groups cooperate, conflict, hold rules and change. Information bears on each. Cooperation rests on whom people trust to tell the truth. Conflict grows from false reports and withheld facts. Rules include the records and checks that institutions keep. Change includes how ideas, habits and rumours spread. The strategy adds three concepts and reuses Communication, Knowledge, Norms, Institutions, Power and Diffusion. It borrows no mechanism from biology or computing. Sequence: The paper''s order is the spine: structure, then receivers, then spread with no central sender. Structure comes first so children can tell what was left behind from what was made to tell later people. Each band revisits all three at a higher level. K-2: sort traces from messages, pass a message on. 3-5: set a message beside a trace, trust a call, watch a habit spread. 6-8: ask who made the evidence, catch a false report, follow a rumour. 9-12: judge who can check a record, weigh two explanations of a legend. Paper''s three dimensions: structure without a sender is translated (Separate things made for another purpose (a ruin, a worn path, an old bill) from things made to tell later people (a chronicle, a memoir). A ruin has no sender. A bill has one but was not written for later readers. Either becomes information when someone reads it with a question. A coin is both.); systems that use information is translated (Leave out evolved receivers, cues and signals. Teach the human counterpart: reasons, practices and institutions that people build to send, record and check information (writing, press, archives, courts, schools), plus reliability, perspective, interests and misinformation, deliberate or careless. Start from students'' own ideas of information, knowledge and truth.); decentralized processing is translated (Use spread with no central sender: a stadium wave, a habit seen by other classes, a rumour. Add a legend that leaders pushed and many repeated. Explain spread by each person''s reasons, norms and contact. Students often assume a boss behind a pattern, so they ask who was in charge, and who passed it on.) False friends: Biologie Kl. 5 (Vögel, Säugetiere), Kl. 8 (Nerven- und Hormonsystem) and Kl. 10 (Genetik) use ''information'' for cues, nerve signals and genes. Here information needs a person or group with goals who reads or passes it on. Genes and nerve signals stay with Bio-Core. Informatik Kl. 7 (Informationen und Daten) and Kl. 8 (Vernetzte Systeme) treat information as coded data held and moved by machines. Here it depends on a person''s question and trust. No bits, channels or noise. Machine cases stay with Computational-Core. ''Code'' in genetics and programming means a fixed mapping or instructions. In Social-Core a code is a convention that people made and can change by agreement, such as a language or a code of conduct. Gene and program code talk is left out. In biology a ''signal'' can be a trait shaped for sending and ''meaning'' a link between cue and response. Here a signal is a sign people agree on, such as a whistle, and meaning is shared and can be disputed. No selection is involved. Geschichte Kl. 5 ''Quelle'' includes objects made for another purpose, such as a tool or a bill. ''Informationsquelle'' in Sachunterricht Kl. 4 and Technik/Computer Kl. 5-6 means a book or website made to inform. Social-Core''s Source covers both and asks which kind a thing is. Some students treat information and truth as one thing, and tie it to knowledge (Grossnickle et al. 2015, via the paper). Here information can be true or false. Knowledge is what a group holds and can justify. Ethik Kl. 7 media work needs this split.', 'AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it. Grounding paper: Eirdosh and Hanisch (2026, in press).  Open checks for reviewers are under reviewNotes in scripts/data/information-strategies.json.', '["No Social-Core concept for information existed. The three new concepts (Information, Source, Misinformation) are a proposal. Reliability was folded into Source after review.","The paper reports no study of students'' conceptions of information in biology, and its framework has no classroom test. The Social-Core reading is an extension. Nothing here has been tried in a classroom.","Grossnickle et al. (2015) and Alexander et al. (2012) are used as the paper reports them (p. 5). Their grade ranges were not checked and no K-2 sample is known.","The grounding set has no source on how children or teenagers judge the reliability of sources or trust informants. The Rome, rumour and grading stations rest on design bets.","The evidence on students assuming a boss behind a spread pattern (S40, S41) comes from older students and adults. Its use at grades 3-5 is a design bet.","Sachsen tags no information topic before Sachunterricht Kl. 3, so the K-2 stations have no Sachsen link.","Not built: a first probe of students'' own ideas of information, knowledge and truth before the first stations (the paper says learners bring everyday intuitions, p. 6), a dimension 1 station at 9-12 on digital trails (GRW Kl. 8 ''Datenspur''), a station where a trace and a report about the same event disagree, a market or price station, and a shared knowledge project station.","Archives and courts are named in the strategy but have no station of their own."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('052de431-4465-53e3-b00c-4fa75088c542', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', 'ec43321e-dd60-5bd9-bdfc-2e4e17dd7b85', 1, 'K-2, Communities Then and Now (precursor, dimension 1: structure without a sender). Children meet three kinds of evidence about market day in the town square: a worn cobblestone and an old market scale, an old photo, and an older person''s story. They sort them into two boxes: used for something else, and made to tell us. They say what each one shows and ask the older person what changed. Example: Market day in the square: a worn cobblestone and a market scale, an old photo, and a grandparent''s story. Shown as: Picture cards sorted into two boxes: used for something else, and made to tell us. New demand: Ask for the first time who made a thing and why. Sort things that were used from things made to tell. Evidence for this age is thin, so treat it as a trial. Concepts: Social Change, Source, Information. Thinking tools: Tinbergen''s Questions K-2 (Market day in the town square, long ago and).', 'd221821a-01a1-54d7-a156-df38866a1dc5', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', 'ec43321e-dd60-5bd9-bdfc-2e4e17dd7b85', 'fee774c4-aec9-50a5-92e9-66fbc776714f', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', 'ec43321e-dd60-5bd9-bdfc-2e4e17dd7b85', '0c562b16-dc7a-5b57-9a7c-843e0b069e2c', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('db61fa15-c660-5633-88da-57e1154ba688', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', 'c4836b7e-c2ac-5eda-9368-08e410453278', 2, 'K-2, Groups We Belong To and Their Rules (precursor, dimension 2: systems that use information). The class lines up and passes the line-up rule by whisper from child to child. The last child says it aloud. The class compares it with the picture card the teacher kept and with what the teacher says. Children say where the rule changed, why it might have changed, and how a group can keep it right. Example: The line-up rule whispered down a row of six children and checked against a picture card. Shown as: A row of children and one picture card to check the last whisper against. New demand: Notice that a message can arrive changed, give one reason why, and name one way a group checks it. This is the first time a message is held against its first form. Concepts: Communication, Norms, Group, Information. Thinking tools: Tinbergen''s Questions K-2 (The class rule of lining up at the door.).', '80e5794a-74bf-5c07-a435-71b6f6c7c0c7', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', 'c4836b7e-c2ac-5eda-9368-08e410453278', '0c562b16-dc7a-5b57-9a7c-843e0b069e2c', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('baa79b8b-cbc1-533c-ba68-a43ea8bb3e0b', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', 'f21b382b-ed4a-5e4e-b69b-d603834fbbe9', 3, '3-5, Roles and Why Rules Differ (full, dimension 1: structure without a sender). Groups read the ''Quiet please'' sign in the library, then count how many children talk during a ten-minute visit. The sign is a message made to inform. The count shows the custom, what people do when nobody is told. They compare the two, say what each tells about the rule, and name the role of the person who keeps it. Example: The library sign ''Quiet please'' and a tally of who talks during a class visit. Shown as: Two-column sheet: what the sign says, what the tally shows, with a row for where they differ. New demand: Set a message beside evidence of what people do and say where they agree or differ. A rule written down and a custom can part ways. Concepts: Norms, Source, Role, Information. Thinking tools: Tinbergen''s Questions 3-5 (Talking rules in the library and on the playground). Sachsen topics: geschichte Kl. 5: Orientierung in der Vergangenheit; geschichte Kl. 5: Von der Steinzeit zur Hochkultur – Menschen organisieren ihr Zusammenleben; sachunterricht Kl. 3: Begegnung mit Raum und Zeit.', '380fb2a2-69bf-5950-9997-0b88e441278c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', 'f21b382b-ed4a-5e4e-b69b-d603834fbbe9', 'fee774c4-aec9-50a5-92e9-66fbc776714f', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', 'f21b382b-ed4a-5e4e-b69b-d603834fbbe9', '0c562b16-dc7a-5b57-9a7c-843e0b069e2c', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('ab048fc2-5f30-595b-9468-aa38c024d9da', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', '3d964122-338c-548e-882b-d833d2ec4209', 4, '3-5, Why People Cooperate or Hold Back (full, dimension 2: systems that use information). In a passing game a teammate shouts ''I''m free!''. Some calls are true and some are false. Pairs fill a two-by-two table: I pass or keep, the call was true or false, with a sentence in each cell. They name one reason to call falsely, then say what makes a player trust the next call: past calls, a friend, or a rule against false calls. Example: A teammate shouts ''I''m free!'' in a school football game. Pass or keep? Shown as: Two-by-two table: pass or keep against call true or false, with a sentence in each cell. New demand: Add the truth of the call as a second unknown. Say what makes a listener trust the next call. Evidence is thin at this age. Concepts: Cooperation, Incentive, Source, Communication. Thinking tools: Payoff Matrices 3-5 (Passing the ball or keeping it in a school); Causal Mapping 3-5 (Who brings a cake to the class party table.).', 'd7094e85-8ed0-5b69-b6e3-5fcf954eb582', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', '3d964122-338c-548e-882b-d833d2ec4209', 'fee774c4-aec9-50a5-92e9-66fbc776714f', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('c13374cd-78f8-5740-9ce3-2409cb646d2d', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', 'aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c', 5, '3-5, How a Practice Spreads (precursor, dimension 3: decentralized processing). Children trace how a recycling habit reached the whole school. They gather what happened from three sources: a child in each class, a teacher and the school newsletter. They draw who saw it, who told whom and who joined. They ask whether anyone announced it. The class also tries a wave with no leader and says who was in charge. Example: A recycling habit that spread from one class to the whole school, and a wave in the school hall. Shown as: Cards for classes joined by arrows that show who saw or told whom. New demand: Explain a pattern that many people made without a boss. Name one reason for each person who passed it on. Concepts: Diffusion, Communication, Source, Knowledge. Thinking tools: Causal Mapping 3-5 (A recycling habit spreading from one class to the); Analogy Mapping 3-5 (How a bread recipe and a marbles game each). Sachsen topics: sachunterricht Kl. 4: Zusammen leben und lernen; sachunterricht Kl. 4: Medien – Informationsbeschaffung und -aufbereitung.', '1c6776e1-7f70-52c2-8c93-00089fb0056c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', 'aae0bca6-2dfa-5fb1-a2bd-4e8d4381b87c', 'fee774c4-aec9-50a5-92e9-66fbc776714f', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('bdc4eafd-048d-59ce-a202-fd0e0fc4977f', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', 'fd772a6a-0dd8-5410-96c5-79f75443183c', 6, '6-8, Why Societies Differ (full, dimension 1: structure without a sender). Students compare what survives from Rome and from the peoples the Romans called Germani. They sort evidence into traces (tools, pottery, graves, house outlines) and reports (a Roman writer''s account, made for readers in Rome). For each piece they ask who made it, for whom and what it leaves out. A coin was money and also carried an emperor''s picture, so it fits both boxes. Example: A Roman coin found beyond the frontier, and a Roman writer''s account of the Germani, written for readers in Rome. Shown as: Two-column sort of traces and reports, each with who made it, for whom and what is missing. New demand: Say what a trace can show that a report cannot, and the reverse. Find a piece that is both, and say what it leaves out. Concepts: Culture, Source, Knowledge. Sachsen topics: geschichte Kl. 6: Die römische Zivilisation und ihre prägende Wirkung für Europa.', '4d0aa77c-9673-5444-9a04-d490aab9f7fc', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', 'fd772a6a-0dd8-5410-96c5-79f75443183c', 'fee774c4-aec9-50a5-92e9-66fbc776714f', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('c57cc1e3-0931-502a-9d78-8e128f7c5f2c', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', '2de4fac1-1590-5260-a501-d040c57c2acf', 7, '6-8, Shared-Resource Problems (full, dimension 2: systems that use information). Students extend the garden-club water table with a second choice: what each member reports about their use, true or false. They find the cell where a false report pays when nobody checks. They redo the table with a meter or a shared logbook and note what the check costs and who does it. Example: Invented case: two garden-club members share one water tank. Each says how much they took. Shown as: Two tables: reports unchecked and reports checked by a meter, changed cells shaded, plus a cost column. New demand: Separate what a person does from what the person reports. Show how a check changes the payoffs and say who pays for it. Concepts: Incentive, Collective Action, Misinformation, Source. Thinking tools: Payoff Matrices 6-8 (Two garden-club members sharing one water tank.); Causal Mapping 6-8 (A garden club sharing one water tank in a).', 'd9a7d40a-15a6-5d10-a17c-777b612924a0', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', '2de4fac1-1590-5260-a501-d040c57c2acf', '14789508-8343-5763-9898-c66f4d5eab41', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', '2de4fac1-1590-5260-a501-d040c57c2acf', 'fee774c4-aec9-50a5-92e9-66fbc776714f', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('b8901a58-9ab5-5c47-b5b4-92993d4a3867', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', '9ef944f3-b11a-5327-9082-b53ba736a834', 8, '6-8, How Norms Are Enforced (full, dimension 3: decentralized processing). A rumour about who cut in at the canteen goes round the class group chat. Students map who passed it on and why: to warn, to joke, to join in. They mark where the story changed, ask who started it and who could stop it, and say whether passing it on works as disapproval of queue-jumping. Example: Invented case: a rumour in the class group chat about who jumped the canteen queue. Versions differ. Shown as: Map of people with arrows for who told whom, a reason on each arrow and a mark where the story changed. New demand: Give each person who passes it on a reason of their own. Find where nobody was in charge and where a rule or role could change the spread. Concepts: Norms, Diffusion, Misinformation, Power. Thinking tools: Tinbergen''s Questions 6-8 (Queueing at the school canteen.); Causal Mapping 6-8 (Keeping the school yard litter-free once monitors stop checking.). Sachsen topics: ethik Kl. 7: Medien: Ein Spiegel der Wirklichkeit; gemeinschaftskunde-rechtserziehung-wirtschaft Kl. 8: Jugendliche und Medien in einer digitalisierten Welt; technik-computer Kl. 5-6: Grundlagen im Umgang mit digitalen Medien; ethik Kl. 7: Verstehen und Verständigung.', '380fb2a2-69bf-5950-9997-0b88e441278c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', '9ef944f3-b11a-5327-9082-b53ba736a834', '14789508-8343-5763-9898-c66f4d5eab41', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('6e471448-69a4-505a-bd8f-f8cde9255104', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', '56eb4828-57c2-589b-92ba-180f901b2443', 9, '9-12, Formal Institutions and Informal Norms (extended, dimension 2: systems that use information). Students compare fair grading under a central exam board and under each teacher''s own marks, asking what a mark tells someone who was not in the room. Rows: who made the record, who can check it, who can challenge it, who gains from it. They rank the breaks by how far each lets outsiders rely on the mark. Example: Invented case: a final mark read by a university, set by a central exam board or by one teacher. Shown as: Two-column map with four shared rows on the record, a break column and a ranking. New demand: Judge an institution by how well outsiders can check its records. Separate what a mark says from who can confirm it. Concepts: Institutions, Source, Power, Incentive. Thinking tools: Analogy Mapping 9-12 (Fair grading under a central exam board and under).', '4e1ba9af-f7f2-5a32-b3c5-83baca7d1265', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', '56eb4828-57c2-589b-92ba-180f901b2443', 'fee774c4-aec9-50a5-92e9-66fbc776714f', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('38f2d40f-633e-5511-8c10-1fa3e97f7039', '632b26a3-cfd6-561a-95c0-e290c76bf3fb', '504c7645-bc71-5a81-a114-cd2d598d1621', 10, '9-12, Explaining Large-Scale Change (extended, dimension 3: decentralized processing). Students take the stab-in-the-back legend after 1918, a false claim that civilians had betrayed an undefeated army. They set two explanations of its spread side by side: army leaders pushed it from above, or many people repeated it because it suited them. They sort speeches, newspapers and letters for each, mark where one cause alone fails, and tag each claim about who spread it supported, disputed or a guess. Example: The stab-in-the-back legend after 1918: army leaders told it, and parties, newspapers and many ordinary people repeated it. Shown as: Two-column evidence sheet, one column per explanation, each claim tagged supported, disputed or a guess. New demand: Weigh two explanations against the same evidence and say where each alone fails. Ask who gained from the story, who it blamed and who checked it. Concepts: Diffusion, Power, Misinformation, Agency. Thinking tools: Causal Mapping 9-12 (Trade unions growing in industrial towns over generations.); Tinbergen''s Questions 9-12 (Votes for women in Germany: decreed in November 1918,). Sachsen topics: geschichte Kl. 9: Deutschlands Weg von der Demokratie zur Diktatur.', '1c6776e1-7f70-52c2-8c93-00089fb0056c', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('7f604bf5-2f90-5f00-9160-30e9265971c4', '504c7645-bc71-5a81-a114-cd2d598d1621', '14789508-8343-5763-9898-c66f4d5eab41', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
UPDATE projects SET introduction = introduction || '

Information. This space treats information in its own terms. Information is what people record, tell, share, withhold, check and rely on to act or to find out. It includes things made for another purpose, such as a ruin or an old bill, and messages made to tell. People give it meaning together and build rules and institutions to send, keep and check it. The aim is to explain why groups cooperate, conflict, hold rules and change. Information bears on each. Cooperation rests on whom people trust to tell the truth. Conflict grows from false reports and withheld facts. Rules include the records and checks that institutions keep. Change includes how ideas, habits and rumours spread. The strategy adds three concepts and reuses Communication, Knowledge, Norms, Institutions, Power and Diffusion. It borrows no mechanism from biology or computing. The paper''s order is the spine: structure, then receivers, then spread with no central sender. Structure comes first so children can tell what was left behind from what was made to tell later people. Each band revisits all three at a higher level. K-2: sort traces from messages, pass a message on. 3-5: set a message beside a trace, trust a call, watch a habit spread. 6-8: ask who made the evidence, catch a false report, follow a rumour. 9-12: judge who can check a record, weigh two explanations of a legend. The strategy rests on the paper by Eirdosh and Hanisch (2026, in press) and is a proposal. AI drafted it and no subject expert has reviewed it.' WHERE id = '7f604bf5-2f90-5f00-9160-30e9265971c4' AND introduction NOT LIKE '%Information. This space treats information in its own terms.%';
INSERT INTO literature_references (project_id, literaturebase_id, title, authors, year, doi, venue, type, status, notes, tags)
SELECT '7f604bf5-2f90-5f00-9160-30e9265971c4', 'OE-LITERATURE-eirdosh-hanisch-2026', 'Understanding Information as an Interdisciplinary Concept in Biology Education', '["Eirdosh, Dustin","Hanisch, Susan"]'::jsonb, 2026, NULL, NULL, NULL, 'draft', 'Grounding paper of the information strategy of Social-Core (AI-drafted 2026-10-27, no expert review).', ARRAY['information', 'proposed-link']::text[]
WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = '7f604bf5-2f90-5f00-9160-30e9265971c4' AND literaturebase_id = 'OE-LITERATURE-eirdosh-hanisch-2026');

-- Computational-Core
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('017cfeb0-94bb-5f7b-9fd9-154e6ffee431', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'concept', 'Regularity', 'A repeat, trend or dependence in recorded values that a program can use to predict the next value or to shorten the data. It exists whether or not anyone sent it. The more of it, the fewer bits the data need.', 'e49e585b-b47d-553f-adff-0381568f4589', '{"definition":"A repeat, trend or dependence in recorded values that a program can use to predict the next value or to shorten the data. It exists whether or not anyone sent it. The more of it, the fewer bits the data need.","vocabulary":"COMPUTATIONAL-CORE-proposed","conceptbase_id":"OE-CONCEPT-computational-core-regularity","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"The Information definition joins a pattern and its measure. Dimension 1 needs the pattern named on its own, so students can meet it before any sender, receiver or bit count.","excludes":"A message, a signal or anything sent on purpose. Also any claim that the pattern means something or that the machine notices it.","basis":["paper p.10-12","OE-LITERATURE-eirdosh-hanisch-2026","OE-LITERATURE-shannon-1948","own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('38cbbc81-ce5c-540a-8267-948de8ed694d', 'bac697ab-febe-5111-a5bd-f266b8b2d837', 'concept', 'Encoding Scheme', 'A rule or table, written down by people, that maps data to symbols and back, so a decoder can recover what an encoder wrote. Encoder and decoder must use the same one.', '6fe408fb-82b8-5eb7-84a5-eecf93c7946f', '{"definition":"A rule or table, written down by people, that maps data to symbols and back, so a decoder can recover what an encoder wrote. Encoder and decoder must use the same one.","vocabulary":"COMPUTATIONAL-CORE-proposed","conceptbase_id":"OE-CONCEPT-computational-core-encoding-scheme","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"Dimension 2 needs a name for what a decoder must share. It also separates a code as an agreed table from a code as genes or as program text.","excludes":"DNA or any genetic code, program source text, and encryption. An encoding scheme need not hide anything.","basis":["OE-LITERATURE-shannon-1948","paper p.4","paper p.7","own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Keep the accepted meaning. A regularity makes data predictable, so a receiver that applies it needs fewer bits, and a fully predictable message adds none (paper p. 2). The count is relative to a stated set of possible messages and says nothing about meaning or truth.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '55fe3edf-e31e-5b23-bd12-64f764124269';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Data stay recorded values. A sensor log is data with or without a regularity. Data become a message only when a sender puts them into an agreed encoding scheme for a receiver. A pattern in a log is not a signal.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'e49e585b-b47d-553f-adff-0381568f4589';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Includes learned representations: the numbers a trained model builds from data, such as weights. They stand for something only to the people who read them. Nobody wrote a scheme for them, and reading them is hard work. Text in a character table is read through a stated scheme.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '6fe408fb-82b8-5eb7-84a5-eecf93c7946f';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Shannon''s sender-receiver model is an abstraction. It hides meaning, how sender and receiver came to share an encoding scheme, and the parallel, many-part dynamics of distributed systems (paper p. 4, 22). Students name what a model hides, as C1:3-5 already asks of a chart.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '5dc1875c-652e-5a9e-a1eb-c15e52549e17';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The group result, such as a total, an agreement or a route, is held by no single component. Students find where it is stored at each step. No component receives all the inputs. Cells, bees and crowds stay out of this space.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '4663fd6b-bad8-5bc8-972c-b1f24cf0dd4d';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Neural networks appear as one model whose parameters, the weights, are adjusted from data. The units are numeric functions and training changes numbers. Paper p. 24 asks how meaning arises in natural and artificial neural systems. This space covers the artificial side as numbers. Interdisciplinary holds the comparison.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '63046d12-d8d7-5830-b2df-ac2833e913f0';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Includes what a program does with input that fails its specification, such as a mistyped or damaged message. A check cannot catch input that is valid but misleading, such as a padded spam message. People write the checks before the input arrives.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'af273d2a-ae9d-5d1a-8b74-3c23e0eba18b';
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, evidence_note, gaps, status)
VALUES ('ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', 'bac697ab-febe-5111-a5bd-f266b8b2d837', '3eceaf9b-fb08-4821-ba31-77f3b3f478d2', 'information-across-the-bands', 'Information across the grade bands', 'vertical_horizontal', 'Information is a pattern that narrows the set of messages a receiver must tell apart, counted in bits. A receiver is a program that applies a rule. The count rests on a stated set of possible messages and an encoding scheme both ends share. Data are recorded values. Meaning and truth lie outside the count.', 'Information in Computational-Core. Sense: Information is a pattern that narrows the set of messages a receiver must tell apart, counted in bits. A receiver is a program that applies a rule. The count rests on a stated set of possible messages and an encoding scheme both ends share. Data are recorded values. Meaning and truth lie outside the count. Boundary: Information is a property of data and messages in systems that people built. A program is a receiver only in the sense that it applies a decoding rule. No intention, belief, honesty, meaning or understanding is credited to a machine. No organism, selection, gene or DNA serves as explanation, and ''code'' never means DNA. Meaning, truth and trust belong to people and to other spaces. Aim: The aim is a formal vocabulary for what computing systems do, with no intention credited to machines. The strategy keeps information a measure on data and codes, so the space stays formal. Each of the paper''s three ideas becomes something a program does or a person built: a program uses a regularity, a decoder follows a shared code, many simple rules give a group result. Words such as listen, trust, know and understand give way to follow a rule, check and adjust a parameter. Sequence: Pattern first, then receivers, then decentralized dynamics, as in the paper. Machine receivers follow written rules, so receivers can start early without agent talk. K-2: tell a recorded pattern from a sent note, and see that a robot follows only its key card. 3-5: use a pattern in a rule and trace a wrong result to its input. 6-8: two ends agree on an encoding scheme, and many nodes follow one local rule. 9-12: count bits, test a trained model with crafted input, compare central and distributed designs. Paper''s three dimensions: structure without a sender is translated (A regularity in recorded values (a repeat, a trend, a link between two columns) exists without a sender, and a sensor log holds regularities and no message. It becomes information only for a program built to use it, to predict the next value or to shorten the data. The bit count comes at 9-12.); systems that use information is translated (Three parts. A decoder must share the encoder''s encoding scheme, which people wrote down. A system''s behaviour changes through design, versions and training on data. Noisy, mistyped, spam or crafted input breaks a rule or slips past it. Evolved goals, selection and honest signals are left out.); decentralized processing is translated (Many components follow the same simple local rule with no central controller, and the group result is held by no single component. Taught with agent-based simulations, averaging among neighbouring nodes and file-sharing networks. Cells, bees and crowds are left to other spaces.) False friends: Code. Biology says genes ''code for'' traits and computing treats coding as human-made (paper p. 7). Here a code is a table people wrote, so it has an author. That is why ''DNA is a code'' misleads. Sachsen Biologie Kl. 10 Genetik lists ''genetischer Code''. Information as data plus meaning. Sachsen Informatik Kl. 7 lists ''Unterscheidung der Begriffe'' and ''Darstellung von Informationen als Daten'', so information may be taught as what data stand for. Here the bit count leaves meaning out. Information as true facts. Children define information with ''knowledge'' and ''truth'' (paper p. 5). A false message carries as many bits as a true one. Sachsen Informatik Kl. 8 asks students to judge information sources. That is a question of truth, outside the count. Signal, sender, receiver. In biology a signal is a trait shaped for communication. Here a signal is a physical quantity, a message is a block of symbols under a protocol, and a receiver is a program that applies a rule (Sachsen Informatik Kl. 9 Netzwerke). Learning, memory, neuron. Sachsen Biologie Kl. 8 teaches memory and nerve cells. Here memory is storage, learning is adjusting parameters from data, and a neural network is numeric units with weights. The paper''s neural-network bridge (p. 24) is read this way.', 'AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it. Grounding paper: Eirdosh and Hanisch (2026, in press). Sources cited by the stations: shannon-1948, shannon-1956. Open checks for reviewers are under reviewNotes in scripts/data/information-strategies.json.', '["No study found on how students aged 5 to 18 understand information in computing contexts. The paper reports none for biology (p. 6). Every station is a design bet to test.","Sachsen tags show no informatics topic before Kl. 7 and none on agent-based models. Stations 1 to 4 and 6 have no Sachsen informatics home. Station 3 links to chart reading and the sun''s daily arc, a loose fit.","AI4K12 has no counterpart for bits, shared codes, check bits or distributed systems.","Neural networks are absent from the vocabulary. Station 8 uses a one-neuron model without a new concept. Whether the space grows toward AI4K12 is open decision D2.","No station for the paper''s misinformation payoff matrix (p. 21-22). Payoffs for a spam sender and a filter designer belong to people.","Learned representations at depth (embeddings, hidden layers) have no stage. Only the weights of one unit appear.","How the Sachsen Informatik Kl. 7 topic defines information and data is unknown. Only the topic statements were read."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('a63970a2-9dc6-59ab-841a-b719e3e67cc6', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', '528aba11-45e9-5ec4-b5da-4ddf071ff6a2', 1, 'K-2, Sorting, Labelling and Symbols (precursor, dimension 1: structure without a sender). Children get two strips. One shows light readings a sensor took each hour: dark, dark, bright, bright, and so on. The other is a card message a friend laid out with symbols. They find the part of the sensor strip that repeats and say what comes next. They say which strip was sent to them and which was only recorded. Example: Sensor strip: dark, dark, bright, bright, dark, dark. Friend''s cards: house, arrow, ball. Only the second was sent. Shown as: Two strips of coloured squares and symbol cards, laid side by side. New demand: Tell a pattern that was recorded from a note that was sent, and use the pattern to say what comes next. Concepts: Data, Regularity, Representation.', 'e49e585b-b47d-553f-adff-0381568f4589', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '528aba11-45e9-5ec4-b5da-4ddf071ff6a2', '017cfeb0-94bb-5f7b-9fd9-154e6ffee431', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('384720d1-c358-575c-b051-7d804207dbf8', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', '04edbe9b-292d-5101-a009-fc46ead81427', 2, 'K-2, Machines Follow Rules People Write (precursor, dimension 2: systems that use information). Pairs play programmer and robot. The programmer lays out arrow cards. The robot moves a floor figure using only a key card that says what each arrow means. They swap in a second key card for the same arrows and watch the path change. They say who wrote each key and what the robot does with an arrow that is not on its key. Example: Key A: up arrow means one step forward. Key B: up arrow means one step back. Same cards, two different paths. Shown as: A row of arrow cards, two key cards and a floor grid. New demand: Say that the robot can only follow the key it was handed, so the same cards give different moves under different keys. Concepts: Program, Encoding Scheme, Representation. Thinking tools: Analogy Mapping K-2 (A recipe card for a sandwich beside arrow cards); Causal Mapping K-2 (A toy that plays a song when its button). AI4K12: 4-D-i-k-2-EU, 2-A-ii-k-2-EU.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '04edbe9b-292d-5101-a009-fc46ead81427', '38cbbc81-ce5c-540a-8267-948de8ed694d', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '04edbe9b-292d-5101-a009-fc46ead81427', '7cbe05dd-828c-5b43-a156-a5fab17ee554', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"04edbe9b-292d-5101-a009-fc46ead81427","stage":"C3:K-2 Machines Follow Rules People Write","relation":"related","strength":"weak","why":"Information station of comp: Pairs play programmer and robot. The programmer lays out arrow cards. The robot moves a floor figure using only a","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '7cbe05dd-828c-5b43-a156-a5fab17ee554' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"04edbe9b-292d-5101-a009-fc46ead81427"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('dbd5f06a-3fc5-5bb8-b3b5-b62027c3bf1f', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', 'f95b2dff-2e43-597e-b8c6-a1857c0f60c7', 3, '3-5, Recording and Charting Data (full, dimension 1: structure without a sender). Groups record the room temperature each hour in a table and chart it. They write a rule that predicts the next reading and test it on a new day. They shuffle the same numbers and test the rule again. In pairs they play twenty questions to find a hidden reading, with and without the rule, and count the questions. Example: Hourly readings rise after lunch, so ''one degree warmer than the hour before'' predicts well. Shuffled readings give the rule nothing to use. Shown as: A table and line chart of one day''s readings, beside a shuffled copy. New demand: Tell data a rule can predict from data it cannot, and show that the rule cuts the number of questions needed to find a reading. Concepts: Data, Regularity, Representation, Information. Thinking tools: Tinbergen''s Questions 3-5 (A newsletter chart of favourite lunches used to plan). Sachsen topics: geographie Kl. 5: Ausgewählte Ballungsgebiete; sachunterricht Kl. 3: Begegnung mit Raum und Zeit. AI4K12: 3-A-i-3-5-EU.', 'e49e585b-b47d-553f-adff-0381568f4589', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'f95b2dff-2e43-597e-b8c6-a1857c0f60c7', '017cfeb0-94bb-5f7b-9fd9-154e6ffee431', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('490396d7-04d9-5324-bbf9-bf3a93f6d5c1', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', '8c7bc083-021f-5891-b502-de2f708a1e09', 4, '3-5, Sequences, Loops and Conditions (precursor, dimension 2: systems that use information). Children build a class-poll program that counts votes for each lunch choice. They test it with a vote typed ''Pizzza'' and a vote entered twice. They trace the stored counts, find where the program went wrong, and add a condition that catches one kind of bad vote. They say what the program cannot tell. Example: The poll counts ''Pizzza'' as a new lunch choice. A check against the list of choices catches it. A double vote from one child passes the check. Shown as: A trace table of the stored counts after each vote. New demand: Explain a wrong result from the input and the program''s rules alone, and say what a check can catch and what it cannot. Concepts: Program, State, Specification. Thinking tools: Tinbergen''s Questions 3-5 (A class poll program that shows last week''s totals). AI4K12: 2-B-i-3-5-LO.', 'd5b9a8e1-3f8d-5100-9a23-b4d0aae498f9', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '8c7bc083-021f-5891-b502-de2f708a1e09', '9da5c00f-5c22-564c-855a-bd331a81a6c5', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"8c7bc083-021f-5891-b502-de2f708a1e09","stage":"C2:3-5 Sequences, Loops and Conditions","relation":"related","strength":"weak","why":"Information station of comp: Children build a class-poll program that counts votes for each lunch choice. They test it with a vote typed ''Pizzza''","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '9da5c00f-5c22-564c-855a-bd331a81a6c5' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"8c7bc083-021f-5891-b502-de2f708a1e09"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('945fcfe6-8b30-5163-abe0-e66e8dadbf17', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', 'f63a89a8-8a27-5cd6-acdf-7ed9f179442b', 5, '6-8, Encoding Text, Images and Numbers (full, dimension 2: systems that use information). Pairs encode a short word in ASCII using one character table and pass the bits on paper strips. The receiver decodes with the same table, then with a different one. The teacher flips one bit in transit. They add a check bit to each character, detect the flip, and write the decoder''s specification, including what it does when the check fails. Example: ''HI'' read with a shifted table gives other letters. Flipping the last bit of the byte for I (01001001) gives H (01001000). A check bit that keeps the count of 1s even shows the flip. Shown as: Bit strips under two character tables, each character followed by a check bit. New demand: Show that the same bits give different data under different encoding schemes, and that a check bit detects one flipped bit but cannot say which one changed. Concepts: Encoding Scheme, Specification, Representation, Data. Thinking tools: Causal Mapping 6-8 (A short text message encoded and decoded with two). Sachsen topics: informatik Kl. 7: Informationen und Daten. AI4K12: 3-C-i-6-8-EU.', '38cbbc81-ce5c-540a-8267-948de8ed694d', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'f63a89a8-8a27-5cd6-acdf-7ed9f179442b', '38cbbc81-ce5c-540a-8267-948de8ed694d', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'f63a89a8-8a27-5cd6-acdf-7ed9f179442b', '462b17fa-2c6f-51bb-9903-3f409e5b4a54', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"f63a89a8-8a27-5cd6-acdf-7ed9f179442b","stage":"C1:6-8 Encoding Text, Images and Numbers","relation":"related","strength":"weak","why":"Information station of comp: Pairs encode a short word in ASCII using one character table and pass the bits on paper strips. The receiver","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '462b17fa-2c6f-51bb-9903-3f409e5b4a54' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"f63a89a8-8a27-5cd6-acdf-7ed9f179442b"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('444cdd7a-a6a0-5002-83f2-2067cc3ef6a6', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', '45c484c9-e753-5bb3-86af-086bc28fce31', 6, '6-8, Agent-Based and Feedback Models (full, dimension 3: decentralized processing). Students run an agent-based model of 100 sensor nodes in a grid. Each node holds a number. A random pair of neighbours repeatedly both take the average of their two numbers. No node sees the whole grid. They watch the nodes settle near the overall average, say where that average is stored at the start and the end, then change the pairing rule and report the effect. Example: Nodes start with random temperatures. After many pairings each node shows about the grid average. No node ever received all the readings. Shown as: A grid of coloured cells and a line graph of the highest and lowest value over time. New demand: Say where the group result is stored at each step, and show that changing the local rule changes the result for the whole group. Concepts: Distributed System, Simulation, State, Feedback. Thinking tools: Causal Mapping 6-8 (A traffic model in which each car slows for); Tinbergen''s Questions 6-8 (Buses bunching together in a model of buses on).', '4663fd6b-bad8-5bc8-972c-b1f24cf0dd4d', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('4f2de5fc-249d-5211-a057-45d5f67e00a5', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', '22e68923-d1f7-54a7-9cb5-6a3591c04a02', 7, '9-12, Information, Compression and the Limits of Representation (extended, dimension 1: structure without a sender). Students compress three files with a program: a thousand repeats of one letter, a page of text, and a thousand random bytes. They relate each compressed size to how predictable the file is. They count the bits needed to pick one of N equally likely messages and change N. They name what the bit count leaves out. Example: A thousand A''s shrink to a few bytes. Random bytes do not shrink. One of 8 equally likely messages costs 3 bits, true or false. Shown as: A table of original size, compressed size and bits per message for each file. New demand: Show that the more predictable a file, the fewer bits it needs, and name what the count leaves out: meaning, truth and how the two ends came to share an encoding scheme. Concepts: Information, Regularity, Representation, Data. Thinking tools: Causal Mapping 9-12 (A running total of 0.1 added ten thousand times). Sachsen topics: informatik Kl. 7: Informationen und Daten. AI4K12: 3-C-i-9-12-EU.', '55fe3edf-e31e-5b23-bd12-64f764124269', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '22e68923-d1f7-54a7-9cb5-6a3591c04a02', '017cfeb0-94bb-5f7b-9fd9-154e6ffee431', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', '22e68923-d1f7-54a7-9cb5-6a3591c04a02', '8e570e2f-fb6a-538f-b0c8-e4db3e017c98', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"22e68923-d1f7-54a7-9cb5-6a3591c04a02","stage":"C1:9-12 Information, Compression and the Limits of Representation","relation":"related","strength":"weak","why":"Information station of comp: Students compress three files with a program: a thousand repeats of one letter, a page of text, and a thousand","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '8e570e2f-fb6a-538f-b0c8-e4db3e017c98' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"22e68923-d1f7-54a7-9cb5-6a3591c04a02"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('86dd286f-3e64-5c6a-a333-c5d0a67c3382', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', 'e6374470-9533-570e-8d98-0e5b24060f4d', 8, '9-12, Machine Learning, Search and Distributed Systems Compared (extended, dimension 2: systems that use information). Students train a one-neuron spam model by hand, then in a spreadsheet, on 40 short messages labelled spam or not spam, using counts of five words. They print the weights, retrain on a different 40 to make version 2, and compare weights and errors. They write a message that slips past a version and explain the wrong output from the data, the weights and the input. Example: ''free'' gets a high weight if set A has it mostly in spam, and a low one if set B has it in ordinary mail. Padding spam with negatively weighted words lowers its score. Shown as: A table of word counts, a weight for each word and each message''s score. New demand: Trace a wrong output through the weights back to the training data. Say what retraining fixes and what it cannot, and why the model cannot be said to know, trust, lie or understand. Concepts: Machine Learning, Data, Model, Specification. Thinking tools: Causal Mapping 9-12 (A video recommender that is retrained each week on); Tinbergen''s Questions 9-12 (A video recommender that is retrained each week on); Analogy Mapping 9-12 (A spam filter, a route finder and a file-sharing). Sachsen topics: informatik Kl. 9: Künstliche Intelligenz; informatik Kl. 8: Vernetzte Systeme. AI4K12: 3-A-ii-9-12-LO, 3-B-ii-6-8-LO, 3-C-iii-9-12-EU.', '63046d12-d8d7-5830-b2df-ac2833e913f0', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('bac697ab-febe-5111-a5bd-f266b8b2d837', 'e6374470-9533-570e-8d98-0e5b24060f4d', '7892570b-8ea8-5ffd-b44f-70685a5f18cb', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
