UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"e6374470-9533-570e-8d98-0e5b24060f4d","stage":"C3:9-12 Machine Learning, Search and Distributed Systems Compared","relation":"related","strength":"weak","why":"Information station of comp: Students train a one-neuron spam model by hand, then in a spreadsheet, on 40 short messages labelled spam or not","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '03a77945-b5db-5f3e-bd8d-0b145a24ad71' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"e6374470-9533-570e-8d98-0e5b24060f4d"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('5d9ad7c6-ca20-56a3-a1dc-10a91f6ed7af', 'ae5b8cb6-aae8-56dd-9648-7ed19b555e3e', 'e6374470-9533-570e-8d98-0e5b24060f4d', 9, '9-12, Machine Learning, Search and Distributed Systems Compared (extended, dimension 3: decentralized processing). Students run a file-sharing network on cards. Twelve peers hold pieces of a file, each of eight pieces on three peers, and no peer holds all of them. They trace a request, remove two peers and check that the file can still be rebuilt. They repeat with one server holding the file and compare what each design guarantees when a part fails. Example: Eight pieces, each held by three of twelve peers. Remove any two peers and every piece survives. Remove the single server and the file is gone. Shown as: A card for each peer listing its pieces, and a diagram of who asks whom. New demand: Compare a central and a distributed design on what each guarantees when parts fail, and say why no peer needs to hold the whole file. Concepts: Distributed System, State, Specification. Thinking tools: Analogy Mapping 9-12 (A spam filter, a route finder and a file-sharing). Sachsen topics: informatik Kl. 9: Netzwerke.', '4663fd6b-bad8-5bc8-972c-b1f24cf0dd4d', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;
UPDATE projects SET introduction = introduction || '

Information. This space treats information in its own terms. Information is a pattern that narrows the set of messages a receiver must tell apart, counted in bits. A receiver is a program that applies a rule. The count rests on a stated set of possible messages and an encoding scheme both ends share. Data are recorded values. Meaning and truth lie outside the count. The aim is a formal vocabulary for what computing systems do, with no intention credited to machines. The strategy keeps information a measure on data and codes, so the space stays formal. Each of the paper''s three ideas becomes something a program does or a person built: a program uses a regularity, a decoder follows a shared code, many simple rules give a group result. Words such as listen, trust, know and understand give way to follow a rule, check and adjust a parameter. Pattern first, then receivers, then decentralized dynamics, as in the paper. Machine receivers follow written rules, so receivers can start early without agent talk. K-2: tell a recorded pattern from a sent note, and see that a robot follows only its key card. 3-5: use a pattern in a rule and trace a wrong result to its input. 6-8: two ends agree on an encoding scheme, and many nodes follow one local rule. 9-12: count bits, test a trained model with crafted input, compare central and distributed designs. The strategy rests on the paper by Eirdosh and Hanisch (2026, in press) and is a proposal. AI drafted it and no subject expert has reviewed it.' WHERE id = 'bac697ab-febe-5111-a5bd-f266b8b2d837' AND introduction NOT LIKE '%Information. This space treats information in its own terms.%';
