WHERE NOT EXISTS (SELECT 1 FROM literature_references WHERE project_id = 'bac697ab-febe-5111-a5bd-f266b8b2d837' AND literaturebase_id = 'OE-LITERATURE-eirdosh-hanisch-2026');
