-- Interdisciplinary
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f8a6c279-be0f-5e6b-ba30-091ebebf85b1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cue', 'A pattern that varies in step with something else and that a receiver uses to expect or act, although nothing produced it in order to be used. The receiver''s ability to use it is what makes it a cue.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"definition":"A pattern that varies in step with something else and that a receiver uses to expect or act, although nothing produced it in order to be used. The receiver''s ability to use it is what makes it a cue.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cue","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"Communication mentions the cue inside its sender frame. Dimension 1 needs the pattern first, before any sender exists, from K-2. A separate entry lets stages tag cue against signal and gives sensing and shortcut cases a home.","excludes":"A cue is no message and has no sender, and it is not a hint given on purpose. It can mislead and says nothing about cause. What made the receiver able to read it differs by domain: selection, learning or design.","basis":["paper p.17-18 (Maynard Smith and Harper 2003, cue and signal, Fig. 3; the book was not read here)","OE-LITERATURE-maynard-smith-harper-2003","paper p.10-11 (rotting fruit, stars)","OE-LITERATURE-planer-godfrey-smith-2021","paper p.13 (Planer and Godfrey-Smith: reliable associations reduce uncertainty)","AI4K12 3-C-iii-6-8-eu (irrelevant correlations in training data)","non-biology senses: own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('06f176bd-988e-5ac4-91de-ea334089a10b', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cue (biology)', 'A feature of the setting that organisms evolved to respond to: rotting-fruit smell, day length, the sun''s position, a predator''s eyes. Selection shaped the receiver''s response. The feature itself was not shaped to inform the receiver.', 'f8a6c279-be0f-5e6b-ba30-091ebebf85b1', '{"level":"discipline-facet","facet_of":"Cue","definition":"A feature of the setting that organisms evolved to respond to: rotting-fruit smell, day length, the sun''s position, a predator''s eyes. Selection shaped the receiver''s response. The feature itself was not shaped to inform the receiver.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cue-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('4d8f3dc8-a5fd-5988-8fd4-0f7111a65fa1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cue (cognition)', 'A feature a person has learned to read: dark clouds before rain, a frown, a hush in the classroom. Experience builds many of these links, and some, such as attention to faces, start early in infancy. People can misread a cue.', 'f8a6c279-be0f-5e6b-ba30-091ebebf85b1', '{"level":"discipline-facet","facet_of":"Cue","definition":"A feature a person has learned to read: dark clouds before rain, a frown, a hush in the classroom. Experience builds many of these links, and some, such as attention to faces, start early in infancy. People can misread a cue.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cue-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('9214ece0-fafb-5990-8438-b3a5b01401fd', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cue (culture)', 'A trace people read as evidence although nobody left it as a message: footprints, tree rings, worn paths, pottery pieces. Records written to tell are a different kind of source. Readers check how the trace formed.', 'f8a6c279-be0f-5e6b-ba30-091ebebf85b1', '{"level":"discipline-facet","facet_of":"Cue","definition":"A trace people read as evidence although nobody left it as a message: footprints, tree rings, worn paths, pottery pieces. Records written to tell are a different kind of source. Readers check how the trace formed.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cue-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('3908014e-55b2-594b-85a8-2fbfec787a9f', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cue (technology)', 'A physical quantity that a device is built to read, such as light, temperature or a pulse. The device is designed. The quantity was not produced for the device.', 'f8a6c279-be0f-5e6b-ba30-091ebebf85b1', '{"level":"discipline-facet","facet_of":"Cue","definition":"A physical quantity that a device is built to read, such as light, temperature or a pulse. The device is designed. The quantity was not produced for the device.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cue-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('6eee1ae8-370a-5199-a838-aa982c440a02', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Cue (AI and computation)', 'An input feature a trained program uses because it varied in step with the label in the training data, such as a background that matches the label. It may be unrelated to the cause. The program cannot tell.', 'f8a6c279-be0f-5e6b-ba30-091ebebf85b1', '{"level":"discipline-facet","facet_of":"Cue","definition":"An input feature a trained program uses because it varied in step with the label in the training data, such as a background that matches the label. It may be unrelated to the cause. The program cannot tell.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-cue-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('fd22524c-2533-5525-af5b-39371442114e', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Signal', 'A pattern produced because of its effect on a receiver, so that producer and receiver are both set up to use it. What set them up differs by domain: selection, convention or design.', '301b8eed-edd6-5c71-91df-5219467c24fb', '{"definition":"A pattern produced because of its effect on a receiver, so that producer and receiver are both set up to use it. What set them up differs by domain: selection, convention or design.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-signal","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"The paper''s second dimension turns on cue against signal. Communication''s biology sense already holds the signal idea. A separate entry lets stages tag the signal alone and records that technology and AI4K12 use the same word for a measured quantity.","excludes":"A signal needs a producer shaped or built to send it. It does not require intention, honesty or meaning. An electronic or AI4K12 ''signal'' that nobody shaped for the receiver is a cue here.","basis":["paper p.16-18 (Lewis; Skyrms; Maynard Smith and Harper; Figs. 2-3)","OE-LITERATURE-planer-godfrey-smith-2021","OE-LITERATURE-maynard-smith-harper-2003","OE-LITERATURE-skyrms-2010","Maynard Smith and Harper and Skyrms were not read here","vocabulary: Communication note","AI4K12 1-B-i-3-5-eu (sensory signals)","convention and design senses: own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('78a3a107-3264-507b-87cb-4e1e175575a1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Signal (biology)', 'A trait or act that selection shaped because it changes what a receiver does: alarm calls, the honeybee dance, moth eyespots. Sender and receiver traits evolved together. No intention is needed. Inside a body, sender-receiver wording models causal roles (paper p.18-19).', 'fd22524c-2533-5525-af5b-39371442114e', '{"level":"discipline-facet","facet_of":"Signal","definition":"A trait or act that selection shaped because it changes what a receiver does: alarm calls, the honeybee dance, moth eyespots. Sender and receiver traits evolved together. No intention is needed. Inside a body, sender-receiver wording models causal roles (paper p.18-19).","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-signal-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('21a810aa-baa1-5fb2-810d-219dcbca67da', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Signal (culture)', 'Words, gestures, flags, sirens and badges that people produce to be read under shared conventions. The sender intends an effect. Conventions can be learned and changed. A signal can be honest, mistaken or false.', 'fd22524c-2533-5525-af5b-39371442114e', '{"level":"discipline-facet","facet_of":"Signal","definition":"Words, gestures, flags, sirens and badges that people produce to be read under shared conventions. The sender intends an effect. Conventions can be learned and changed. A signal can be honest, mistaken or false.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-signal-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bf09c31e-5247-546a-9014-3b6e22d4235d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Signal (technology)', 'A designed variation in voltage, light or radio waves that carries an encoded message under an agreed protocol. Engineers define the code. Noise can corrupt it, and nobody has to understand it.', 'fd22524c-2533-5525-af5b-39371442114e', '{"level":"discipline-facet","facet_of":"Signal","definition":"A designed variation in voltage, light or radio waves that carries an encoded message under an agreed protocol. Engineers define the code. Noise can corrupt it, and nobody has to understand it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-signal-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e6886188-e067-58ad-9496-8375db60a6be', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Signal (cognition)', 'On one account, eye contact and infant-directed speech tell an infant that what follows is meant to teach. The infant then treats what is shown as general knowledge.', 'fd22524c-2533-5525-af5b-39371442114e', '{"level":"discipline-facet","facet_of":"Signal","definition":"On one account, eye contact and infant-directed speech tell an infant that what follows is meant to teach. The infant then treats what is shown as general knowledge.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-signal-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('cadf3aa2-b6a9-548f-9d84-13da72539116', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Signal (AI and computation)', 'A value that one part of a program passes to another, such as a reward signal or an output vector. Designers decide what it stands for. The receiving part responds by rule or by trained weights.', 'fd22524c-2533-5525-af5b-39371442114e', '{"level":"discipline-facet","facet_of":"Signal","definition":"A value that one part of a program passes to another, such as a reward signal or an output vector. Designers decide what it stands for. The receiving part responds by rule or by trained weights.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-signal-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('75b8a947-bdc4-529b-a909-b2d63dd87005', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Meaning', 'What a pattern is for a particular receiver: the responses, expectations or uses that the receiver''s makeup ties to it. The same pattern can mean different things to different receivers, and nothing to one that cannot use it.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"definition":"What a pattern is for a particular receiver: the responses, expectations or uses that the receiver''s makeup ties to it. The same pattern can mean different things to different receivers, and nothing to one that cannot use it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-meaning","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"The paper''s central step runs from structure to meaning, and the vocabulary uses the word in many notes without defining it. A named concept lets stages and stations state where meaning enters and where it stays out, as in a bit count.","excludes":"Meaning is not located in the pattern alone. In biology it needs no sender, consciousness or understanding. ''Meaning'', ''goal'' and ''good'' for a single cell are shorthand and invite anthropomorphic reading (paper p.14). The Communication entry''s ''no meaning is needed'' for animals means human-type meaning.","basis":["paper p.13-15 (Jablonka 2002; Potter and Mitchell 2022; teleosemantics, Macdonald and Papineau 2006 unverified)","paper p.19-20 (Planer and Godfrey-Smith 2021 on meaning as facts about sender and receiver policies)","paper p.8-9, 18 (Kattmann and Levy dispute this reading)","OE-LITERATURE-potter-mitchell-2022","OE-LITERATURE-jablonka-2002","AI4K12 4-A-ii and 4-A-iii (ambiguity; word embeddings)"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('78764438-12ce-5cc6-847f-63a0ea418176', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Meaning (biology)', 'On one account (teleosemantics), a coupling between a pattern and a response that selection shaped. A food chemical means ''approach'' to a bacterium because approaching paid off in earlier generations. The cell holds no goal or picture. Other accounts reject this.', '75b8a947-bdc4-529b-a909-b2d63dd87005', '{"level":"discipline-facet","facet_of":"Meaning","definition":"On one account (teleosemantics), a coupling between a pattern and a response that selection shaped. A food chemical means ''approach'' to a bacterium because approaching paid off in earlier generations. The cell holds no goal or picture. Other accounts reject this.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-meaning-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('dcff7ec8-1f02-51cc-9703-4a9a30fdcc51', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Meaning (cognition)', 'What a percept or word brings to mind, built from experience. Once internal representations sit between input and action, the response no longer follows the input directly, and a person can think about what is absent.', '75b8a947-bdc4-529b-a909-b2d63dd87005', '{"level":"discipline-facet","facet_of":"Meaning","definition":"What a percept or word brings to mind, built from experience. Once internal representations sit between input and action, the response no longer follows the input directly, and a person can think about what is absent.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-meaning-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('23887c40-7d5d-51c2-99e3-fab18b49a4b2', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Meaning (culture)', 'What a speaker intends and a listener takes, under shared conventions that can be learned and changed. Context decides the reading, and the two sides can differ. Words, maps and signs carry meaning for people who share the code.', '75b8a947-bdc4-529b-a909-b2d63dd87005', '{"level":"discipline-facet","facet_of":"Meaning","definition":"What a speaker intends and a listener takes, under shared conventions that can be learned and changed. Context decides the reading, and the two sides can differ. Words, maps and signs carry meaning for people who share the code.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-meaning-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f8019651-3a44-5b5c-ba3a-3abeb205960b', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Meaning (technology)', 'Engineers set meaning aside. A channel moves coded messages and treats all alike, and a message can arrive intact while nobody understands it. Meaning stays with the people who use the message.', '75b8a947-bdc4-529b-a909-b2d63dd87005', '{"level":"discipline-facet","facet_of":"Meaning","definition":"Engineers set meaning aside. A channel moves coded messages and treats all alike, and a message can arrive intact while nobody understands it. Meaning stays with the people who use the message.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-meaning-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('f1539f09-d579-5bea-9cb4-29ff9205f3da', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Meaning (AI and computation)', 'Technical reading: a bit count ignores meaning. A language model places words used in similar contexts near each other, and people read that as closeness in meaning. The program has no experience of what words stand for.', '75b8a947-bdc4-529b-a909-b2d63dd87005', '{"level":"discipline-facet","facet_of":"Meaning","definition":"Technical reading: a bit count ignores meaning. A language model places words used in similar contexts near each other, and people read that as closeness in meaning. The program has no experience of what words stand for.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-meaning-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('10f95bde-6a9e-5b3b-bc6c-1ef81695192d', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Meaning (education)', 'Learners connect a new pattern to ideas they already hold, so one lesson can mean different things to different students. Teachers check what a learner has taken from it.', '75b8a947-bdc4-529b-a909-b2d63dd87005', '{"level":"discipline-facet","facet_of":"Meaning","definition":"Learners connect a new pattern to ideas they already hold, so one lesson can mean different things to different students. Teachers check what a learner has taken from it.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-meaning-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Misinformation', 'A pattern that leads a receiver to expect or do something that does not fit the facts it appears to track. It may be made to mislead, or arise by mistake, by chance or by copying error.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"definition":"A pattern that leads a receiver to expect or do something that does not fit the facts it appears to track. It may be made to mislead, or arise by mistake, by chance or by copying error.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-misinformation","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"Information and Communication say only that messages can mislead. The paper treats dishonest signals as part of dimension 2, and students already link information with truth (p.5, p.20). The 6-8 and 9-12 work needs a named concept.","excludes":"It does not require a lie: honest error counts, and deliberate deceit has its own name in culture (disinformation). A student misconception is another thing. A false signal in biology involves no intent to deceive.","basis":["paper p.20-22 (dishonest signals, mimicry, eyespots, Figs. 4-5)","OE-LITERATURE-grossnickle-2015","OE-LITERATURE-alexander-2012","AI4K12 5-B-ii-3-5-eu (deepfakes)","honest error, noise, copying error and all non-biology senses: own extension of the paper","misinformation against disinformation wording: unverified, common usage"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('efea5019-c9fc-5171-a2c3-487556eff0ac', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Misinformation (biology)', 'A signal or appearance that makes a receiver act as if a state held when it does not, such as moth eyespots that resemble predators'' eyes. On a prominent hypothesis, selection favoured it because the sender gains. No intent is needed.', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', '{"level":"discipline-facet","facet_of":"Misinformation","definition":"A signal or appearance that makes a receiver act as if a state held when it does not, such as moth eyespots that resemble predators'' eyes. On a prominent hypothesis, selection favoured it because the sender gains. No intent is needed.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-misinformation-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('e3028f03-9b48-57cf-a505-43d20ac70768', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Misinformation (culture)', 'False or misleading claims, pictures and rumours that people pass on. Some are made to deceive, some are honest mistakes, and copying can distort them. People check the source, compare reports and ask who gains.', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', '{"level":"discipline-facet","facet_of":"Misinformation","definition":"False or misleading claims, pictures and rumours that people pass on. Some are made to deceive, some are honest mistakes, and copying can distort them. People check the source, compare reports and ask who gains.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-misinformation-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('25316c54-5458-58b7-af0c-fea0589ade64', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Misinformation (technology)', 'A message altered or forged on the way: bits flipped by noise, a spoofed sender address, a phishing email. Error checks catch noise. They do not catch a forged sender.', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', '{"level":"discipline-facet","facet_of":"Misinformation","definition":"A message altered or forged on the way: bits flipped by noise, a spoofed sender address, a phishing email. Error checks catch noise. They do not catch a forged sender.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-misinformation-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('68b3ce50-f976-58a7-88f9-f150f1acc91a', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Misinformation (AI and computation)', 'Fluent but false output from a language model, or a deepfake image made to pass as a record. The program has no aim to deceive. People who build or use it may.', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', '{"level":"discipline-facet","facet_of":"Misinformation","definition":"Fluent but false output from a language model, or a deepfake image made to pass as a record. The program has no aim to deceive. People who build or use it may.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-misinformation-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('d3de9891-5ab3-52aa-a687-fef4cbb99b56', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Misinformation (cognition)', 'A false belief formed from a misleading cue, or a memory rebuilt wrongly at recall. Ideas a person already holds shape which claims that person accepts.', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', '{"level":"discipline-facet","facet_of":"Misinformation","definition":"A false belief formed from a misleading cue, or a memory rebuilt wrongly at recall. Ideas a person already holds shape which claims that person accepts.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-misinformation-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('ec08a335-fac8-5d98-a792-c2d33f661825', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Misinformation (education)', 'Learners practise checking where a claim came from, who made it and what evidence backs it before relying on it. Media lessons teach this as source criticism.', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', '{"level":"discipline-facet","facet_of":"Misinformation","definition":"Learners practise checking where a claim came from, who made it and what evidence backs it before relying on it. Media lessons teach this as source criticism.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-misinformation-education","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('11d4fb16-9b76-532a-946a-7a7c0de5a526', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Perception', 'A receiver''s step from raw input to a reading it can act on. Sensing detects a physical quantity. Perceiving turns the detection into something usable, using what the receiver already holds.', '6c5398e6-801c-55f9-9732-a018ba999e6b', '{"definition":"A receiver''s step from raw input to a reading it can act on. Sensing detects a physical quantity. Perceiving turns the detection into something usable, using what the receiver already holds.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-perception","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"Agency and Information mention sensing in passing. No concept or stage carries it, and the AI4K12 Perception big idea has no counterpart here. Dimension 2 needs it, because what a receiver can pick up limits what counts as information for it.","excludes":"Perception here says nothing on consciousness or experience, and nothing on whether a sensor, a plant or a model feels anything. Perceiving in a program is labelling input with trained categories.","basis":["AI4K12 1-A-i, 1-A-ii, 1-B-i (items in the reviewed alignment''s unmatched list)","paper p.12-14, 24 (receiver competencies; Potter and Mitchell 2022; neural networks)","OE-LITERATURE-potter-mitchell-2022","vocabulary: Information cognition sense and Agency definition"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('816d4b1e-8259-595a-a380-8041496ff448', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Perception (biology)', 'Sense organs and receptor cells detect light, sound, chemicals or touch. Species differ in what they pick up: bees see ultraviolet and echolocating bats hear echoes of their own calls. Plants and microbes sense with no nervous system.', '11d4fb16-9b76-532a-946a-7a7c0de5a526', '{"level":"discipline-facet","facet_of":"Perception","definition":"Sense organs and receptor cells detect light, sound, chemicals or touch. Species differ in what they pick up: bees see ultraviolet and echolocating bats hear echoes of their own calls. Plants and microbes sense with no nervous system.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-perception-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('39cfdbe7-ccca-5dde-8c3d-7ef592adcdc7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Perception (cognition)', 'The brain builds a percept from sensory input and from what the person expects. Combining senses such as sight and sound helps with ambiguous input. Illusions show the building.', '11d4fb16-9b76-532a-946a-7a7c0de5a526', '{"level":"discipline-facet","facet_of":"Perception","definition":"The brain builds a percept from sensory input and from what the person expects. Combining senses such as sight and sound helps with ambiguous input. Illusions show the building.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-perception-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('b38b9ec5-9391-582c-8405-816918ddb354', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Perception (technology)', 'Sensors such as cameras, microphones and accelerometers measure physical quantities and output numbers. A sensor detects only what it was built to measure, and can pick up what people cannot, such as infrared.', '11d4fb16-9b76-532a-946a-7a7c0de5a526', '{"level":"discipline-facet","facet_of":"Perception","definition":"Sensors such as cameras, microphones and accelerometers measure physical quantities and output numbers. A sensor detects only what it was built to measure, and can pick up what people cannot, such as infrared.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-perception-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('5e51f893-40b1-5ef0-906d-9e4025a351db', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Perception (AI and computation)', 'Technical reading: a program maps sensor numbers to labels it was trained to give, such as a word or an object name. AI4K12 calls this extracting meaning from sensory signals. The labels are the trainers'' categories.', '11d4fb16-9b76-532a-946a-7a7c0de5a526', '{"level":"discipline-facet","facet_of":"Perception","definition":"Technical reading: a program maps sensor numbers to labels it was trained to give, such as a word or an object name. AI4K12 calls this extracting meaning from sensory signals. The labels are the trainers'' categories.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-perception-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('88c585e0-b03b-5724-ae14-8964cf5e800c', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Emergence', 'A pattern of a whole system that arises from many parts reacting to local conditions and to one another. No part directs the whole or holds the whole pattern. Parts can be cells, animals, people or programs.', NULL, '{"definition":"A pattern of a whole system that arises from many parts reacting to local conditions and to one another. No part directs the whole or holds the whole pattern. Parts can be cells, animals, people or programs.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-emergence","level":"extension","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","why":"The comparative flagship note lists system and emergence as concepts no space defines. Dimension 3 needs a name for no-controller patterns that claims nothing about quality, as Collective Intelligence does, or about human thinking, as Distributed Cognition does.","excludes":"It does not mean mysterious or unexplainable, and the outcome need not be good. A planned parade is directed and does not count. No controller in the system leaves room for rules, leaders or designers elsewhere.","basis":["paper p.22-23 (cell, quorum sensing, La-Ola wave, brain, norms, machine-human culture)","OE-LITERATURE-resnick-1996","OE-LITERATURE-jacobson-2001","OE-LITERATURE-falandays-2023","S40, S41, S42","technology and AI senses: own extension of the paper"],"draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('817ab119-1a81-56c5-a808-1fc9fcbeba03', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Emergence (biology)', 'Bacterial quorum sensing, ant trails, honeybee nest-site choice and gene regulation in a cell. No molecule, cell or animal holds the whole outcome. Each part reacts to local signals and to others, and the pattern follows.', '88c585e0-b03b-5724-ae14-8964cf5e800c', '{"level":"discipline-facet","facet_of":"Emergence","definition":"Bacterial quorum sensing, ant trails, honeybee nest-site choice and gene regulation in a cell. No molecule, cell or animal holds the whole outcome. Each part reacts to local signals and to others, and the pattern follows.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-emergence-biology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('eb625afe-9a76-5552-ac7c-f9cd2e9c2da7', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Emergence (cognition)', 'Brain activity comes from billions of neurons with no single place where a controlling self sits. People still tend to imagine a small inner controller, and students often explain such patterns by a controlling agent.', '88c585e0-b03b-5724-ae14-8964cf5e800c', '{"level":"discipline-facet","facet_of":"Emergence","definition":"Brain activity comes from billions of neurons with no single place where a controlling self sits. People still tend to imagine a small inner controller, and students often explain such patterns by a controlling agent.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-emergence-cognition","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('89285ccc-5373-5652-a65e-f61088f506a8', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Emergence (culture)', 'A stadium wave, a traffic jam, a passing trend or a spreading norm. A few people cannot reliably start, steer or end it. Institutions can add control, which makes the case partly directed.', '88c585e0-b03b-5724-ae14-8964cf5e800c', '{"level":"discipline-facet","facet_of":"Emergence","definition":"A stadium wave, a traffic jam, a passing trend or a spreading norm. A few people cannot reliably start, steer or end it. Institutions can add control, which makes the case partly directed.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-emergence-culture","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('a4588b9a-f623-57d6-ae3c-bee2dc211e15', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Emergence (technology)', 'Many networks pass messages through routers that each follow local rules, so no one machine controls the whole route. People still set the shared protocols and the rules.', '88c585e0-b03b-5724-ae14-8964cf5e800c', '{"level":"discipline-facet","facet_of":"Emergence","definition":"Many networks pass messages through routers that each follow local rules, so no one machine controls the whole route. People still set the shared protocols and the rules.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-emergence-technology","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
INSERT INTO lpm_schema_elements (id, project_id, element_type, label, definition, parent_id, metadata, status)
VALUES ('bf79bc7a-9d53-5d28-9bc5-33fae14b8b17', '371fce26-d1f3-439b-95df-0a0e38b8a824', 'concept', 'Emergence (AI and computation)', 'Agent-based models give each agent a simple rule and show group patterns such as flocks. A neural network''s output comes from many units and weights. Designers choose the units, the rules and the training.', '88c585e0-b03b-5724-ae14-8964cf5e800c', '{"level":"discipline-facet","facet_of":"Emergence","definition":"Agent-based models give each agent a simple rule and show group patterns such as flocks. A neural network''s output comes from many units and weights. Designers choose the units, the rules and the training.","vocabulary":"OE-INTERDISCIPLINARY-v1.0.0","conceptbase_id":"OE-CONCEPT-oe-interdisciplinary-emergence-ai","proposed_not_in_conceptbase":true,"proposed_on":"2026-10-27","information_strategy":"true","grounding":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb, 'proposed') ON CONFLICT (id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The paper sharpens the accepted entry. A pattern exists with no sender and becomes information only for a receiver able to use it. A bit count states how unlikely a message is among known options and ignores its meaning. Stations tag these points and add meaning. The definition stays.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '6c5398e6-801c-55f9-9732-a018ba999e6b';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The paper splits the accepted structure in two. A cue is read and was never sent. A signal exists because of its effect on a receiver. In the paper selection sets up both sides. Convention and design are this design''s extension. Cue and Signal name the parts. The definition stays.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '301b8eed-edd6-5c71-91df-5219467c24fb';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The entry: a stand-in works only for a user who treats it as one. The strategy applies this to the thought that DNA is a message needing a coder (p.10). DNA is a structure used by machinery that evolved to use it, and a sender is hard to specify (p.11).","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'fe387dcf-751c-59e6-9fa2-8fcc6abecea3';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Students link information with knowledge and truth (paper p.5-6). Knowledge needs a holder with grounds, so a cue, a signal or a stored trace is not yet knowledge. No station tags it. Teachers can use it to separate information, misinformation and what a group has checked.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'b9faf219-7d7f-5791-abca-c738d6130497';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The paper reads organism-level meaning through selection and warns against anthropomorphism for single cells (p.14). The Agency note already needs no intention in biology and gives software designer-set goals. Receivers in biology stations never choose. Sensing is the half of Agency that the new Perception entry covers.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '993c989a-79d2-5262-b20f-9636504623cd';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Receiver competencies can be evolved, developed or learned (paper p.12). The strategy uses Learning for the within-lifetime case: a child learns which cue to trust, a program adjusts numbers. Selection explains the across-generations case. Stations ask which of these made the receiver able to read a pattern.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '241ac4b1-00b3-517c-b3b5-10029f1efdc6';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"The paper cites Brinkmann et al. on machine intelligences and human cultures (p.23). The AI sense of Culture, a proposed extension, is the home for the machine-culture case in station 7. Its debate note applies: whether machines learn socially is open, and the station says so.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '8c0525a4-0873-52c6-a097-8915714a33ae';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Feedback loops make an input''s significance depend on context in a cell (paper p.22). Many emergent cases include a loop, and the Emergence entry does not require one. Negative feedback damps change and positive feedback amplifies it. Station 7 uses the AI sense, where outputs return as later input.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'b8b2412c-6f27-54f8-b612-4c595d3e9059';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Collective Intelligence compares a group with its members and needs a measure of doing better. Emergence names patterns with no controller whether or not they are good. Stations use Collective Intelligence only when quality is compared, as in the jar-guess case. Bee nest choice fits both.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = '4e4ec762-ee46-53d3-afe3-da41c3d3f6af';
UPDATE lpm_schema_elements SET metadata = metadata || jsonb_build_object('information_strategy_note', '{"note":"Distributed Cognition covers thinking spread over people and tools for a human task. Emergence covers patterns with no controller where no thinking task is involved, such as a stadium wave or quorum sensing. A computer network belongs here only when it serves a human thinking task, as the entry says.","proposed_on":"2026-10-27","draft_note":"AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it."}'::jsonb) WHERE id = 'b889941f-8b31-56a6-aef3-e3e9f26f79ca';
INSERT INTO lpm_threads (id, project_id, branch_id, slug, title, thread_type, connecting_idea, narrative, evidence_note, gaps, status)
VALUES ('505bd745-736c-5715-bdcf-89f8ccc30b02', '371fce26-d1f3-439b-95df-0a0e38b8a824', '6d484dde-6529-4bc6-a486-05521ddc76c8', 'information-across-the-bands', 'Information across the grade bands', 'vertical_horizontal', 'Information is a pattern that varies in step with something else. It becomes information for a receiver that can use the link. What the receiver makes of it, the response or expectation it triggers, is its meaning for that receiver. Whether a sender, an intention or a bit count applies differs by domain.', 'Information in Interdisciplinary. Sense: Information is a pattern that varies in step with something else. It becomes information for a receiver that can use the link. What the receiver makes of it, the response or expectation it triggers, is its meaning for that receiver. Whether a sender, an intention or a bit count applies differs by domain. Boundary: Every cross-domain claim names its domains and the break: is a sender or intention needed, did selection shape the receiver, does a bit count capture meaning, is there a controller. On one account (teleosemantics, p.14) biological meaning is a selection-shaped coupling, and ''goal'' for a cell is shorthand. Machines get no belief or understanding. It does not claim that all systems process information alike. Aim: The space joins the disciplinary readings and says where a shared word stops meaning the same thing. This strategy makes that its main work and models the paper''s recommendations: the three dimensions in the paper''s order, with the step from structure to meaning as the central contribution. Stations 5, 6 and 10 fill a table of where the shared word breaks. Perception and sensing get a home that no stage carried. Anything beyond biology is the design''s own extension of the paper. Sequence: The paper''s order is kept. K-2 sorts patterns nobody sent from patterns made to tell. Grades 3-5 compare what different receivers can pick up and ask who sends a passed-on pattern. Grades 6-8 ask what shaped the receiver and what the pattern means to it: cue, signal, honesty, bit counts. Grades 9-12 remove the controller and test where sender, receiver and meaning stop applying. Evolution enters at 3-5 and returns at 6-8 and 9-12. Dimension 3 starts at 9-12 because evidence for younger students is thin. Paper''s three dimensions: structure without a sender is used (Structure comes first, as in the paper. Students meet patterns nobody sent, such as paw prints, clouds and DNA, and sort them from patterns made to tell. At 6-8 a bit count measures how unlikely a message is and ignores meaning. Examples widen from biology and weather to culture, technology and AI.); systems that use information is used (Students ask what made each receiver able to use a pattern and what it means. Meaning has different grounds: on the teleosemantic account (p.14) a selection-shaped coupling in a bacterium, and in people also intention and convention. Cue, signal, signalling games, misinformation and pathways follow the paper. Perception and non-biology cases are own extension.); decentralized processing is used (Students explain whole-system patterns with no controller in the map: cells, swarms, a stadium wave, a feed. A neural-network station sets brains beside trained networks, as the paper suggests. Students then test designed systems that do have a rule-setter. That contrast is the design''s addition.) False friends: Information. Bits in Informatik Kl. 7 (Informationen und Daten) count binary digits and storage and ignore meaning. Media topics in Ethik Kl. 7 need truth and source checks. Genetik Kl. 10 uses the word for DNA. Stations 5 and 10 set them side by side. Signal. In biology a trait produced for its effect on a receiver. In sensors and AI4K12 a ''sensory signal'' is a measured quantity that nobody shaped for the receiver, called a cue here. KMK also uses signal for signal transduction inside cells. Code. ''Genetic code'' invites the question who coded it (paper p.10). Here a code maps one pattern to another. Design sets it in technology and convention in culture. The genetic code''s origin is debated. Genetik Kl. 10 teaches it, Informatik Kl. 7 binary numbers. Sender-receiver model. Biologie Kl. 5 names it for dogs and cats, Informatik Kl. 8 covers e-mail, Ethik Kl. 7 covers talk. One diagram can fit all three. The biological account needs no intention, a router no understanding, a speaker intends to be understood. Meaning. In biology, on the teleosemantic account (paper p.13-14), a coupling between a pattern and a response that selection shaped. In people it can also rest on intention and shared conventions. In AI4K12 perception ''extracts meaning'' by assigning labels that trainers chose. Source. In history a source is evidence a student reads (Geschichte Kl. 5, Orientierung in der Vergangenheit). In Shannon''s model a source produces messages. In Jablonka''s account a source becomes input when a receiver can react to its form. Here, ask who reads it.', 'AI-drafted on 2026-10-27 from the paper by Eirdosh and Hanisch (2026, in press), the vocabulary and stages of the space, the Sachsen tagging and the thinking-tool strategy. No subject-matter expert has reviewed it and no classroom has tested it. Grounding paper: Eirdosh and Hanisch (2026, in press). Sources cited by the stations: shannon-1948, grossnickle-2015, levy-2011. Open checks for reviewers are under reviewNotes in scripts/data/information-strategies.json.', '["No classroom study of the three-dimension framework exists, and the authors found no study of students'' conceptions of information in biology (paper p.6). Every station is a proposal to test.","The evidence bank covers component skills such as analogy, causal maps, payoff games and systems thinking. It holds no study of information. Most stations rest on design bets, and each station''s evidence field names the thin ones.","Dimension 3 has stations only at 9-12. A 6-8 precursor such as a class wave or an ant-trail model is left out because systems-thinking evidence for younger students is thin (S37, S40, S41).","AI4K12 items on digital encoding at 9-12 (1-A-iii) and on feature extraction and abstraction pipelines (1-B-ii to 1-B-iv) have no station. They belong to Computational-Core. A neural-network precursor at 3-5 or 6-8 is not placed, because no stage there could host it without adding a topic.","The stage concept lists still carry the old concepts. Cue, Signal, Meaning, Misinformation, Perception and Emergence appear in stations only until a person tags the stages.","The Sachsen sample has no information topic for Kl. 1-2, so station 1 has no Sachsen anchor, and station 3 runs ahead of Genetik in Kl. 10.","Not built: a station that maps the stimulus-response model taught in Sachsen Biologie Kl. 8 (Reflexbogen) to the cue and receiver model (paper p.14, 19), a joint Biologie, Informatik and Ethik lesson (paper p.25), a station on Knowledge and truth (paper p.5-6), and any evolution work at K-2."]'::jsonb, 'proposed')
ON CONFLICT (project_id, slug) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('a3a2629f-494e-565e-bb74-03b825a3b005', '505bd745-736c-5715-bdcf-89f8ccc30b02', '9fc65a59-5de1-51ad-ad30-a9c0faca177a', 1, 'K-2, Groups, Rules, and Tools (precursor, dimension 1: structure without a sender). Children collect things that tell them something though nobody made them to: paw prints in mud, dark clouds, the smell of baking. They sort the cards, then add a few things made to tell, such as a stop sign and a wave. They say who can use each pattern: a dog, a child, a toy robot. Some will say clouds are for rain. Ask who made them to tell. Example: Paw prints tell a child that an animal passed by. A drawn stop sign was made to tell drivers. Shown as: Two sorting mats of picture cards, with a ''who can use it?'' sticker on each card. New demand: Notice that a pattern can tell something though nobody made it, and that who it tells depends on who can use it. Concepts: Communication, Information, Cue, Representation. Domains: biology, culture, technology. Thinking tools: Analogy Mapping K-2 (A bird finding seeds and a toy robot rolling). AI4K12: 2-A-ii-k-2-LO, 1-A-i-k-2-LO.', '301b8eed-edd6-5c71-91df-5219467c24fb', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '9fc65a59-5de1-51ad-ad30-a9c0faca177a', 'f8a6c279-be0f-5e6b-ba30-091ebebf85b1', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '9fc65a59-5de1-51ad-ad30-a9c0faca177a', 'c3f37ec9-653b-5278-a28f-3a0f1f23aaa9', 'related-weak') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"9fc65a59-5de1-51ad-ad30-a9c0faca177a","stage":"I1:K-2 Groups, Rules, and Tools","relation":"related","strength":"weak","why":"Information station of int: Children collect things that tell them something though nobody made them to: paw prints in mud, dark clouds, the smell","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = 'c3f37ec9-653b-5278-a28f-3a0f1f23aaa9' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"9fc65a59-5de1-51ad-ad30-a9c0faca177a"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('006f1272-06f1-5096-94e9-2f43c0dc1094', '505bd745-736c-5715-bdcf-89f8ccc30b02', '31b2be29-7a8c-5f98-a447-55ecf57f1ff9', 2, '3-5, Comparing How Different Living Things Act, Learn, and Teach (precursor, dimension 2: systems that use information). Students compare what a bee, a dog, an insect-eating bat, a child and a camera can pick up in the same garden: colours, smells, echoes, heat. A table lists the pattern, the organ or sensor, and who can use it. They ask why a bee sees flower patterns that a child cannot, and try an illusion to see the brain fill in. Example: Flowers carry ultraviolet patterns that a bee sees and a child does not. A thermal camera shows heat that eyes miss. Shown as: Table with one row per receiver: pattern picked up, organ or sensor, who can use it. New demand: Same surroundings, different receivers. Say what each can use and why, with a first selection story: bees that saw flower patterns found more nectar and raised more young. Mark what a camera does that a sense organ does not. Concepts: Perception, Information, Cue, Agency. Domains: biology, cognition, technology, AI and computation. Thinking tools: Analogy Mapping 3-5 (A kitten learning to hunt, a child learning to). Sachsen topics: sachunterricht Kl. 3: Mein Körper und meine Gesundheit; biologie Kl. 5: Säugetiere in ihren Lebensräumen. AI4K12: 1-A-i-3-5-LO, 1-A-ii-3-5-LO, 1-B-i-3-5-EU.', '11d4fb16-9b76-532a-946a-7a7c0de5a526', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
