UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"31b2be29-7a8c-5f98-a447-55ecf57f1ff9","stage":"I2:3-5 Comparing How Different Living Things Act, Learn, and Teach","relation":"related","strength":"weak","why":"Information station of int: Students compare what a bee, a dog, an insect-eating bat, a child and a camera can pick up in the","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '472994cc-973e-5ec7-a1f8-3d2bc504d260' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"31b2be29-7a8c-5f98-a447-55ecf57f1ff9"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('7b48557d-9475-52cf-b759-d3d5c9c2a249', '505bd745-736c-5715-bdcf-89f8ccc30b02', 'db1fca08-0dcf-5910-a3df-2de902e8630a', 3, '3-5, Comparing Biological and Cultural Transmission (full, dimension 1: structure without a sender). Students set two things that are passed on side by side: eye colour from parent to child and the rules of a game taught to a new class. For each they ask who sends it, what reads it, what can change on the way and whether anyone meant to send it. They treat DNA as a structure that cell machinery uses and ask who its sender would be. Example: Nobody means to send eye colour to a child. A classmate is told the rules of a playground game on purpose. Shown as: Two-column table with rows for holder, sender, what reads it, change on the way, and meant or unmeant. New demand: Add the question ''did anyone mean to send it?'' to a passing-on comparison and see that the answer differs between the two columns. Concepts: Inheritance, Transmission, Information, Communication. Domains: biology, culture. Thinking tools: Analogy Mapping 3-5 (Eye colour passing to a child, and a playground); Tinbergen''s Questions K-2 (Curly hair that runs in a family, and a).', '71010850-ffce-5968-b6a5-38c0b8599620', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('2dae3dc9-a687-5f06-bc96-81f040f99160', '505bd745-736c-5715-bdcf-89f8ccc30b02', '3a112595-4435-5db0-950d-ca7c6da5160d', 4, '6-8, Agency, Niche Construction, and Selection (full, dimension 2: systems that use information). Students draw the paper''s two causal maps for a forager. In the cue map, a smell leads to a response that selection shaped in the receiver only. In the signal map, sender trait and receiver response are shaped together. They write what each pattern means to the receiver as the response it triggers. They then add a second cue and see how two cues settle an unclear reading. Example: Rotting-fruit smell is a cue for a fly and an alarm call is a signal. A person combines sight and sound, and a self-driving car combines camera and radar. Shown as: Two causal maps with arrows, a ''means to the receiver'' box on each, and a note on what shaped each side. New demand: Say what shaped each side of each map (selection, learning, design) and what each pattern means to that receiver. For a fly, ''means'' only names a response selection favoured. Show a case where a second cue changes the reading. Concepts: Cue, Signal, Meaning, Agency. Domains: biology, cognition, technology, AI and computation. Thinking tools: Causal Mapping 6-8 (Herding families, milk in the diet, and the spread). Sachsen topics: biologie Kl. 6: Wirbellose Tiere in ihren Lebensräumen; biologie Kl. 8: Sinnesorgane, Nerven- und Hormonsystem des Menschen. AI4K12: 1-A-i-6-8-LO, 1-A-ii-6-8-LO.', 'f8a6c279-be0f-5e6b-ba30-091ebebf85b1', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
