UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"3a112595-4435-5db0-950d-ca7c6da5160d","stage":"I2:6-8 Agency, Niche Construction, and Selection","relation":"related","strength":"weak","why":"Information station of int: Students draw the paper''s two causal maps for a forager. In the cue map, a smell leads to a response","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '39633cff-9431-5895-8001-84b472c035d1' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"3a112595-4435-5db0-950d-ca7c6da5160d"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('623e694d-55f2-5e6a-a564-620cbb5e32c3', '505bd745-736c-5715-bdcf-89f8ccc30b02', '6315aad7-35b7-52dc-9dd2-1b82d707a768', 5, '6-8, The General Pattern: Variation, Selection, Transmission (extended, dimension 1: structure without a sender). Students find a hidden pick among 2, 4 and 8 equally likely options with yes-or-no questions and count the questions. They compare two messages of the same size, one trivial and one urgent, and a true and a false one. They list what the count includes and what it leaves out, and who must read the message for it to matter. Example: One of 8 cards takes 3 yes-or-no questions. For a finch beak or an app feature nobody knows the odds, so the count does not apply directly. Shown as: A tally of questions per game, then a table of what a bit count includes and leaves out. New demand: Count uncertainty for equal options, then show that two messages with the same count can differ in meaning, in truth and in who can use them. Concepts: Information, Representation, Transmission, Meaning. Domains: AI and computation, biology, culture. Thinking tools: Tinbergen''s Questions 6-8 (Beak shape in a finch population, and a swipe); Analogy Mapping 6-8 (A school floor plan, a child''s mental picture of). Sachsen topics: informatik Kl. 7: Informationen und Daten.', '6c5398e6-801c-55f9-9732-a018ba999e6b', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '6315aad7-35b7-52dc-9dd2-1b82d707a768', '75b8a947-bdc4-529b-a909-b2d63dd87005', 'proposed-information-1') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('67a7e2d6-ebdf-5022-9e77-5546f14d402a', '505bd745-736c-5715-bdcf-89f8ccc30b02', 'ad0173a4-5c64-5d05-96ac-2b61810c4153', 6, '6-8, Culture as Transmitted, Institutions as Stabilizing Structures (full, dimension 2: systems that use information). Students fill the paper''s payoff table for an alarm-call game: states of the world, receiver acts and payoffs for both sides, and see which pairings pay. They add a mimic that copies a predator''s eyes and see which pairing now pays the sender. They compare a rumour and a phishing email in a break table: who gains, who meant it, can the receiver check? Example: In the table''s made-up numbers an alarm call pays caller and listeners. Moth eyespots may scare birds by copying a predator''s eyes. A phishing email copies a bank. Shown as: Payoff table for states, receiver acts and both payoffs, plus a break table: who gains, who meant it, can it be checked. New demand: Separate a false pattern shaped by selection, one made on purpose, one made by mistake and one made by noise, and say which a receiver can check. Concepts: Misinformation, Signal, Incentive, Selection. Domains: biology, culture, technology. Thinking tools: Payoff Matrices 6-8 (Birds that fight over a food patch and birds); Payoff Matrices 6-8 (Two fishers sharing one lake.). Sachsen topics: ethik Kl. 7: Medien: Ein Spiegel der Wirklichkeit; informatik Kl. 8: Vernetzte Systeme; gemeinschaftskunde-rechtserziehung-wirtschaft Kl. 8: Jugendliche und Medien in einer digitalisierten Welt.', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', 'ad0173a4-5c64-5d05-96ac-2b61810c4153', '28dd6d23-b5dc-54bc-8bb0-5ad14f75e5a1', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', 'ad0173a4-5c64-5d05-96ac-2b61810c4153', 'fd22524c-2533-5525-af5b-39371442114e', 'proposed-information-2') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('96489d9c-64b1-58c8-8c41-1d4e9a33bc3e', '505bd745-736c-5715-bdcf-89f8ccc30b02', 'e820dc2d-9317-57d1-8475-22a701fc486a', 7, '9-12, Collective Intelligence, Distributed Cognition, and Coevolving Technology (full, dimension 3: decentralized processing). Students collect cases where a pattern of the whole appears with no one steering it: bacteria switching on a shared behaviour, a bee swarm choosing a nest, a stadium wave, routers passing messages, a feed trained on clicks. For each they draw who senses what, mark the missing controller and mark who set the rules. They change one local rule in a swarm simulation. Example: Honeybee scouts compare nest sites and the swarm moves once enough scouts agree. No bee holds the plan. Shown as: Cue and signal arrows between many parts, with an empty box where a controller would sit. New demand: Explain a whole-system pattern with no controller in the map. Find a case where a designer sets the rules and still does not direct the outcome. Is a feed that learns from people a culture? Researchers disagree. Concepts: Emergence, Collective Intelligence, Signal, Feedback. Domains: biology, culture, technology, AI and computation. Thinking tools: Causal Mapping 9-12 (Guessing the beans in a jar, with and without); Analogy Mapping 9-12 (A honeybee swarm choosing a nest site and a). Sachsen topics: biologie Kl. 6: Wirbellose Tiere in ihren Lebensräumen; biologie Kl. 9: Zusammenhänge im Ökosystem; informatik Kl. 9: Netzwerke. AI4K12: 1-C-i-9-12-EU, 5-B-i-9-12-EU.', '88c585e0-b03b-5724-ae14-8964cf5e800c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
