UPDATE lpm_schema_elements SET metadata = jsonb_set(jsonb_set(metadata, '{aligned_stages}', coalesce(metadata->'aligned_stages', '[]'::jsonb) || '[{"stage_id":"e820dc2d-9317-57d1-8475-22a701fc486a","stage":"I1:9-12 Collective Intelligence, Distributed Cognition, and Coevolving Technology","relation":"related","strength":"weak","why":"Information station of int: Students collect cases where a pattern of the whole appears with no one steering it: bacteria switching on a shared","sense_differs":null,"adjacent_band":false,"source":"information-strategy"}]'::jsonb), '{alignment_state}', '"aligned"') WHERE id = '7acc44e4-9963-5e02-9c6c-0477db4c773c' AND NOT (coalesce(metadata->'aligned_stages', '[]'::jsonb) @> '[{"stage_id":"e820dc2d-9317-57d1-8475-22a701fc486a"}]'::jsonb);
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('0807969c-c1a8-5ebc-912b-d1eb66b1dbfa', '505bd745-736c-5715-bdcf-89f8ccc30b02', '5d938d91-e81b-516c-ba58-a234b6d5559f', 8, '9-12, Agency and Niche Construction Across Biological and Technological Systems (extended, dimension 3: decentralized processing). Students wire a small network by hand: three cue cards in, two units that each fire when enough inputs agree, one output. They set the weights from examples, then compare it with a neuron and a trained network. They ask where meaning sits: in a unit, in the weights, or in what the output is used for. Example: Units sum smell, colour and softness cues and fire for ''ripe''. A neuron also sums inputs and fires but is far more complex. A trained image network has millions of such units. Shown as: Hand-built network of cards and weights beside labelled drawings of a neuron and a layered network. New demand: Find no controller inside each system, then name who set the weights. Say how a unit differs from a neuron. Say where meaning sits and why; the question is open. Concepts: Emergence, Perception, Meaning, Representation. Domains: biology, cognition, AI and computation. Thinking tools: Tinbergen''s Questions 9-12 (Bird song, a student''s habit of checking a feed,); Analogy Mapping 3-5 (A kitten learning to hunt, a child learning to). Sachsen topics: biologie Kl. 8: Sinnesorgane, Nerven- und Hormonsystem des Menschen; informatik Kl. 9: Künstliche Intelligenz. AI4K12: 3-B-i-6-8-LO, 3-B-ii-9-12-EU.', '88c585e0-b03b-5724-ae14-8964cf5e800c', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '5d938d91-e81b-516c-ba58-a234b6d5559f', '88c585e0-b03b-5724-ae14-8964cf5e800c', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
