INSERT INTO lpm_object_tags (project_id, data_object_id, schema_element_id, role) VALUES ('371fce26-d1f3-439b-95df-0a0e38b8a824', '5d938d91-e81b-516c-ba58-a234b6d5559f', '75b8a947-bdc4-529b-a909-b2d63dd87005', 'proposed-information-3') ON CONFLICT (data_object_id, schema_element_id) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('229400df-478c-5845-9294-67299ae56341', '505bd745-736c-5715-bdcf-89f8ccc30b02', 'ba60a3be-0135-5b53-b88f-a7aecfe0ed96', 9, '9-12, The Shared Structure of Discovery: Darwin''s Notebooks and the History of Science (extended, dimension 2: systems that use information). Students pick one pathway, a hormone acting on a cell or DNA to protein. They first write each step as ''this changes that'' with no sender-receiver words. They retell it with the words send, read, decode and code, and mark each use as holding, misleading or unclear, using three tests: direction, matching states, active against passive parts. Example: Insulin binds to a cell''s receptor and the cell takes up sugar. A ribosome is said to read a messenger RNA. Does anything read, or does one structure change another? Shown as: Causal chain of steps, then a table: metaphor word, holds or misleads, why. New demand: Keep the information words that track a causal role. Drop reader and coder talk where it implies an interpreter or a designer, and say what each dropped word hid. Concepts: Information, Representation, Analogical Reasoning, Intuitive Theories. Domains: biology, technology, cognition. Thinking tools: Analogy Mapping 9-12 (A breeder choosing pigeons, a wild finch population and); Causal Mapping 6-8 (Herding families, milk in the diet, and the spread). Sachsen topics: biologie Kl. 10: Genetik; biologie Kl. 8: Sinnesorgane, Nerven- und Hormonsystem des Menschen.', '6c5398e6-801c-55f9-9732-a018ba999e6b', 'Leads into the next use of information.')
ON CONFLICT (thread_id, sequence) DO NOTHING;
INSERT INTO lpm_thread_stations (id, thread_id, data_object_id, sequence, role_note, via_element_id, relation_to_next)
VALUES ('f7932e03-9115-54f0-9fb8-64b470e59a38', '505bd745-736c-5715-bdcf-89f8ccc30b02', '396e3dd9-4f22-5160-b6c7-3752caefa1b8', 10, '9-12, Selection Across Biology, Culture, Education, and AI (extended, dimension 2: systems that use information). Students fill one analogy map for four receivers: a bacterium, a bird hearing song, a reader of a news post and a trained classifier. Rows: the pattern, who sent it, what made the receiver able to use it, what it means to that receiver, whether a bit count applies. They name what shaped each receiver and which Selection sense, if any, fits. Break cells use the vocabulary notes. Example: Selection shaped the bacterium. Selection and learning shaped the bird. Convention and learning shaped the reader. Training against a score shaped the classifier. Shown as: Four-column analogy map with a filled break column, built from the does-not-carry-over notes. New demand: Say, row by row, where sender, receiver and meaning stop meaning the same thing, and which case needs no sender at all. For the bacterium, say why ''means'' is shorthand for a response selection favoured. Concepts: Information, Selection, Meaning, Perception. Domains: biology, cognition, culture, technology, AI and computation. Thinking tools: Analogy Mapping 9-12 (A tree of species beside a lineage of language-model); Payoff Matrices 9-12 (A shared-resource dilemma read as animal strategies, neighbours'' water); Analogy Mapping 9-12 (A breeder choosing pigeons, a wild finch population and). Sachsen topics: biologie Kl. 10: Genetik; informatik Kl. 9: Künstliche Intelligenz; biologie Kl. 5: Vögel in ihren Lebensräumen. AI4K12: 1-B-i-9-12-LO, 4-A-ii-9-12-EU, 1-A-ii-9-12-LO.', '6c5398e6-801c-55f9-9732-a018ba999e6b', NULL)
ON CONFLICT (thread_id, sequence) DO NOTHING;
